insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (1,'Tu mapa de tareas','Reto + regalo','Claude',15,'No hace falta conectar nada ni usar datos reales','Haz un mapa de tus tareas y descubre por dónde empezar. Hoy también te llevas el kit de arranque.','⌖','2026-12-01') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (1,'{"secciones":[{"titulo":"Pasos","html":"<ol>\n<li>Abre Claude. Vale la versión gratuita.</li>\n<li>Copia el prompt de este reto y rellena los corchetes con tu semana real. No hace falta que sea exacto: aproximar está bien.</li>\n<li>Responde a sus preguntas. Aquí está el valor: cuanto más concreta seas, mejor sale el mapa.</li>\n<li>Guarda la página que te devuelve y apunta tus tres tareas en la hoja del calendario imprimible. Las volverás a necesitar el día 24.</li>\n<li>Descarga el kit de arranque.</li>\n</ol>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Las tres tareas son tuyas de verdad, no genéricas.</li>\n<li>Los tiempos salen de lo que tú le contaste, no de cifras inventadas.</li>\n<li>La cuarta tarea, la que no conviene delegar, tiene sentido para tu puesto.</li>\n</ul>\n<p>Si el resultado suena a folleto, es que le faltó contexto. Repítelo contando más.</p>"},{"titulo":"Tu regalo: el kit de arranque","html":"<p>Hoy te llevas cinco piezas que vas a usar todo el mes:</p>\n<ul>\n<li><strong>El calendario imprimible</strong>, con los 24 días para ir marcándolos y la hoja de tu mapa de tareas, que retomarás el día 24.</li>\n<li><strong>El prompt del mapa de tareas</strong>, para repetirlo cuando quieras.</li>\n<li><strong>La tarjeta de contexto</strong>: la rellenas una vez y Claude sabrá quién eres y cómo quieres que te hable.</li>\n<li><strong>El semáforo de datos</strong>: qué puedes pegar en una IA y qué no, en dos segundos.</li>\n<li><strong>10 prompts de oficina</strong> listos para copiar.</li>\n</ul>"}],"prompts":[{"titulo":"El mapa de tareas","bloques":[{"tipo":"texto","html":"<p>Copia esto en Claude y rellena lo que está entre corchetes.</p>"},{"tipo":"prompt","html":"<p>Eres mi asesora para empezar a usar la IA en el trabajo. No soy una persona técnica y no sé programar.</p>\n<p>Así es mi semana:</p>\n<ul>\n<li>Mi puesto: [por ejemplo, administrativa en una empresa de 40 personas]</li>\n<li>Lo que hago cada día: [por ejemplo, responder correos de clientes, preparar facturas, actualizar una hoja de cálculo, buscar documentos]</li>\n<li>Lo que hago cada semana: [por ejemplo, un informe de ventas, preparar la reunión del lunes]</li>\n<li>Lo que más tiempo me quita: [escríbelo con tus palabras]</li>\n<li>Lo que más me frustra: [escríbelo con tus palabras]</li>\n<li>Herramientas que uso: [por ejemplo, Outlook, Excel, Drive, un ERP]</li>\n</ul>\n<p>Antes de responder, hazme hasta 5 preguntas para entender mejor mi semana. Una por una.</p>\n<p>Cuando tengas las respuestas, dame mi mapa de tareas:</p>\n<ol>\n<li>Las 3 tareas donde la IA me ayudaría más, ordenadas por lo que me ahorraría.</li>\n<li>Para cada una: cuánto tiempo calculo que me lleva a la semana (usa mis cifras, no inventes ninguna), qué parte haría la IA y qué parte sigo decidiendo yo.</li>\n<li>Por cuál empezar y por qué.</li>\n<li>Una tarea que NO conviene delegar todavía, y el motivo.</li>\n</ol>\n<p>Preséntalo como una página interactiva que pueda guardar, con las tres tareas en tarjetas y el tiempo semanal bien visible.</p>\n<p>Si algo de lo que te he contado no está claro, dímelo en vez de rellenarlo por tu cuenta.</p>","texto":"Eres mi asesora para empezar a usar la IA en el trabajo. No soy una persona técnica y no sé programar.\n\nAsí es mi semana:\n\n- Mi puesto: [por ejemplo, administrativa en una empresa de 40 personas]\n- Lo que hago cada día: [por ejemplo, responder correos de clientes, preparar facturas, actualizar una hoja de cálculo, buscar documentos]\n- Lo que hago cada semana: [por ejemplo, un informe de ventas, preparar la reunión del lunes]\n- Lo que más tiempo me quita: [escríbelo con tus palabras]\n- Lo que más me frustra: [escríbelo con tus palabras]\n- Herramientas que uso: [por ejemplo, Outlook, Excel, Drive, un ERP]\n\nAntes de responder, hazme hasta 5 preguntas para entender mejor mi semana. Una por una.\n\nCuando tengas las respuestas, dame mi mapa de tareas:\n\n1. Las 3 tareas donde la IA me ayudaría más, ordenadas por lo que me ahorraría.\n2. Para cada una: cuánto tiempo calculo que me lleva a la semana (usa mis cifras, no inventes ninguna), qué parte haría la IA y qué parte sigo decidiendo yo.\n3. Por cuál empezar y por qué.\n4. Una tarea que NO conviene delegar todavía, y el motivo.\n\nPreséntalo como una página interactiva que pueda guardar, con las tres tareas en tarjetas y el tiempo semanal bien visible.\n\nSi algo de lo que te he contado no está claro, dímelo en vez de rellenarlo por tu cuenta."}]}],"descargas":[{"titulo":"Calendario imprimible","descripcion":"Los 24 días para colgar y marcar, y la hoja de tu mapa de tareas.","nombre":"calendario-imprimible.pdf","formato":"PDF","url":"/adviento/descargas/b7b094a69c3b/calendario-imprimible.pdf","peso":"143 KB"},{"titulo":"Tarjeta de contexto","descripcion":"Rellénala una vez y pégala al empezar una conversación o en las preferencias de Claude.","nombre":"tarjeta-de-contexto.pdf","formato":"PDF","url":"/adviento/descargas/1a4da2b4a9f1/tarjeta-de-contexto.pdf","peso":"27 KB","copiar":"## Quién soy\n\n**Mi puesto:**\n_(ejemplo: coordinadora de oficina en una empresa de 40 personas del sector logístico)_\n\n**Para quién trabajo:**\n_(ejemplo: dirección, el equipo comercial y los clientes de la zona norte)_\n\n**Qué se espera de mí:**\n_(ejemplo: que la información esté ordenada y que nada se quede sin respuesta)_\n\n## Cómo quiero que me hable\n\n**Tono:**\n_(ejemplo: cercano pero profesional, de tú, sin palabras rebuscadas)_\n\n**Idioma y formato:**\n_(ejemplo: español de España, respuestas cortas, listas solo cuando ayuden)_\n\n**Qué no quiero:**\n_(ejemplo: que me dore la píldora, que use palabras como \"sinergia\", que escriba párrafos enormes)_\n\n## Mis reglas\n\n1. Si te falta información, pregúntamela en vez de inventarla.\n2. Si no estás segura de un dato, dímelo.\n3. _(añade la tuya)_\n4. _(añade la tuya)_\n\n## Lo que nunca te voy a dar\n\n_(ejemplo: datos de clientes con nombre y apellidos, números de cuenta, contratos sin anonimizar)_"},{"titulo":"Semáforo de datos","descripcion":"Qué puedes pegar en una IA y qué no. Para tenerlo a mano.","nombre":"semaforo-de-datos.pdf","formato":"PDF","url":"/adviento/descargas/1b346d1d3099/semaforo-de-datos.pdf","peso":"50 KB"},{"titulo":"10 prompts de oficina","descripcion":"Correos, fórmulas, actas, informes y conversaciones difíciles, listos para copiar.","nombre":"10-prompts-de-oficina.pdf","formato":"PDF","url":"/adviento/descargas/0d4c2a40d92a/10-prompts-de-oficina.pdf","peso":"35 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (2,'Conectores sin miedo','Tip','Claude',5,'Hoy no se conecta nada','Entiende qué puede ver un conector y aprende a revisar sus permisos antes de usarlo.','⚿','2026-12-02') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (2,'{"secciones":[{"titulo":"Qué es un conector","html":"<p>Darle a la IA una llave para que mire una carpeta concreta de tu casa. No le das la casa entera, y la llave se puede quitar cuando quieras.</p>\n<p>Hoy no vas a conectar nada. Solo vas a entender qué pasa cuando conectas, para que mañana lo hagas con tranquilidad.</p>"},{"titulo":"Las cuatro preguntas antes de conectar nada","html":"<ol>\n<li>¿Qué puede ver exactamente? ¿Toda la bandeja o solo lo que le pidas?</li>\n<li>¿Solo lee, o también escribe y envía?</li>\n<li>¿Dónde se quita el acceso, y cuántos clics cuesta?</li>\n<li>¿Tu empresa tiene una política sobre esto?</li>\n</ol>"},{"titulo":"Si no sabes la respuesta a la cuarta","html":"<p>Pregunta a tu responsable o a IT. No es hacer el ridículo: es lo que hace una profesional.</p>\n<p>Y si la respuesta es que no, tranquila: los retos de este calendario que usan conectores tienen una alternativa con datos de prueba. Nadie se queda fuera.</p>"},{"titulo":"Empieza por lo menos sensible","html":"<p>El calendario antes que el correo. Aprendes el mecanismo con algo que no tiene adjuntos ni datos de clientes.</p>"}],"prompts":[],"descargas":[{"titulo":"Checklist de permisos","descripcion":"Para repasar antes de dar acceso a Claude o a cualquier otra herramienta.","nombre":"checklist-permisos.pdf","formato":"PDF","url":"/adviento/descargas/c805d9f98d43/checklist-permisos.pdf","peso":"27 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (3,'Tu primer conector','Reto','Claude (conectores)',15,'Tu calendario, o los correos de prueba si no puedes conectar nada','Conecta tu calendario y pídele a Claude un resumen útil de tu semana. Hay alternativa con datos de prueba.','⟟','2026-12-03') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (3,'{"secciones":[{"titulo":"Pasos","html":"<ol>\n<li>Abre los ajustes de conectores de Claude.</li>\n<li>Conecta solo el calendario. Nada más, aunque te ofrezca el paquete entero.</li>\n<li>Lee qué permisos pide antes de aceptar. Es lo que practicamos ayer.</li>\n<li>Copia el prompt principal de este reto.</li>\n<li>Comprueba que lo que te dice coincide con tu agenda real.</li>\n<li>Termina con el prompt de comprobación: es la mitad del reto.</li>\n</ol>"},{"titulo":"¿Por qué el calendario y no el correo?","html":"<p>El calendario no tiene adjuntos ni datos de clientes. Si algo sale raro, no hay nada que lamentar. El correo llegará más adelante, cuando ya sepas cómo funciona esto.</p>"},{"titulo":"Si no puedes conectar nada","html":"<p>Si tu empresa no lo permite o tu plan no lo incluye, no pasa nada: este reto también es para ti. Descarga los correos de prueba de una semana y pídele lo mismo sobre ese archivo. Aprendes exactamente lo mismo sin conectar nada.</p>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Lo que resume coincide con lo que ves en tu agenda.</li>\n<li>Si una reunión no tiene un asunto claro, te lo dice en vez de inventarse de qué va.</li>\n<li>Sabes dónde se desconecta.</li>\n</ul>"},{"titulo":"La idea que debe quedarse","html":"<p>Un conector no le da acceso a toda tu vida: le da la llave de una puerta concreta, y la llave se devuelve cuando quieras.</p>"}],"prompts":[{"titulo":"El principal","bloques":[{"tipo":"prompt","html":"<p>Mira mi calendario de esta semana y dime:</p>\n<ol>\n<li>Cuántas horas tengo ocupadas en reuniones.</li>\n<li>Qué día tengo más cargado y cuál más libre.</li>\n<li>Si hay algún hueco de dos horas seguidas para trabajar sin interrupciones.</li>\n<li>Si ves alguna reunión que no sé de qué va, dímelo en vez de suponerlo.</li>\n</ol>\n<p>No cambies nada en mi calendario. Solo quiero que me lo cuentes.</p>","texto":"Mira mi calendario de esta semana y dime:\n\n1. Cuántas horas tengo ocupadas en reuniones.\n2. Qué día tengo más cargado y cuál más libre.\n3. Si hay algún hueco de dos horas seguidas para trabajar sin interrupciones.\n4. Si ves alguna reunión que no sé de qué va, dímelo en vez de suponerlo.\n\nNo cambies nada en mi calendario. Solo quiero que me lo cuentes."}]},{"titulo":"Para comprobar","bloques":[{"tipo":"prompt","html":"<p>¿De dónde has sacado cada cosa que me has dicho? Dime qué eventos has usado.</p>","texto":"¿De dónde has sacado cada cosa que me has dicho? Dime qué eventos has usado."},{"tipo":"texto","html":"<p>Así aprendes a pedirle cuentas en vez de fiarte a ciegas.</p>"}]},{"titulo":"Si no puedes conectar nada","bloques":[{"tipo":"prompt","html":"<p>Te paso un archivo con los correos de una semana. Dime cuántos son de clientes, cuántos son internos y cuántos son publicidad. Si alguno no sabes dónde ponerlo, déjalo aparte en vez de forzarlo.</p>","texto":"Te paso un archivo con los correos de una semana. Dime cuántos son de clientes, cuántos son internos y cuántos son publicidad. Si alguno no sabes dónde ponerlo, déjalo aparte en vez de forzarlo.","adjuntos":["bandeja-entrada.csv"]}]}],"descargas":[{"titulo":"Correos de prueba de una semana","descripcion":"120 correos inventados, para practicar sin conectar nada.","nombre":"bandeja-entrada.csv","formato":"CSV","url":"/adviento/descargas/91410ac2738c/bandeja-entrada.csv","peso":"18 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (4,'Un proyecto para tu trabajo','Tip','Claude (Proyectos)',10,'Dos documentos tuyos, sin datos personales','Crea un proyecto que recuerde el contexto de tu trabajo para no repetirlo en cada conversación.','▣','2026-12-04') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (4,'{"secciones":[{"titulo":"Por qué importa más de lo que parece","html":"<p>El día 1 rellenaste la tarjeta de contexto. Hoy aprendes dónde guardarla para no volver a pegarla nunca. Un proyecto recuerda quién eres y qué documentos manejas, y todo lo que hagas dentro sale ajustado a tu trabajo.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Crea un proyecto y llámalo como tu puesto: «Administración», «Coordinación de oficina», lo que sea.</li>\n<li>Pega tu tarjeta de contexto del día 1 en las instrucciones del proyecto.</li>\n<li>Añade la plantilla de instrucciones de este reto, adaptada a ti.</li>\n<li>Sube <strong>dos</strong> documentos que uses de verdad: una plantilla de correo, un procedimiento, un modelo de informe. Pásalos antes por el semáforo de datos.</li>\n<li>Haz la misma pregunta dentro del proyecto y fuera. Compara.</li>\n</ol>"},{"titulo":"La comparación es el reto","html":"<p>No se trata de crear un proyecto, sino de <strong>ver la diferencia</strong>. La misma pregunta fuera del proyecto sale genérica; dentro, sale con tu vocabulario y tus plantillas.</p>"},{"titulo":"Qué documentos subir (y cuáles no)","html":"<p><strong>Sí:</strong> plantillas vacías, procedimientos internos sin nombres, modelos de informe, el glosario de siglas de tu empresa.</p>\n<p><strong>No:</strong> nada con nombres de clientes, importes reales o datos de personal. Eso es semáforo rojo.</p>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>La respuesta dentro del proyecto usa tu vocabulario y tu formato.</li>\n<li>No has subido nada que no debías.</li>\n</ul>"}],"prompts":[],"descargas":[{"titulo":"Instrucciones de proyecto","descripcion":"Plantilla para pegar en las instrucciones de tu proyecto y rellenar con lo tuyo.","nombre":"instrucciones-proyecto.pdf","formato":"PDF","url":"/adviento/descargas/a14c4cbc43f2/instrucciones-proyecto.pdf","peso":"30 KB","copiar":"## Quién soy y qué hago\n\nSoy [puesto] en [tipo de empresa y tamaño]. Mi trabajo consiste sobre todo en [tres o cuatro cosas].\n\nTrabajo con [herramientas: Outlook, Excel, Drive, el ERP que uses].\n\nNo soy una persona técnica. No sé programar y no quiero aprender a hacerlo para esto.\n\n## Con quién me comunico\n\n- **Dirección:** [tono que usas con ellos]\n- **Clientes:** [tono]\n- **Compañeros:** [tono]\n- **Proveedores:** [tono]\n\n## Cómo quiero que me respondas\n\n- En español de España, de tú.\n- Respuestas cortas. Si hace falta extenderse, dímelo y lo pido.\n- Nada de palabras como \"sinergia\", \"disruptivo\" o \"potenciar\".\n- Si me vas a dar una lista de más de cinco cosas, pregúntame antes si la quiero entera.\n\n## Mis reglas\n\n1. Si te falta un dato, pregúntamelo. No lo inventes.\n2. Si no estás segura de algo, dilo claramente.\n3. Cuando me des un número, dime de dónde sale.\n4. No des por hecho cómo funciona mi empresa: pregunta.\n5. Si lo que te pido es mala idea, dímelo antes de hacerlo.\n\n## Lo que nunca te voy a dar\n\nDatos de clientes con nombre, importes reales con el cliente identificado, nóminas, contratos confidenciales ni nada con DNI o datos bancarios.\n\nSi te pido algo que necesite eso, avísame y lo hacemos con datos inventados.\n\n## Vocabulario de mi empresa\n\n- [sigla] = [qué significa]\n- [sigla] = [qué significa]\n- Cuando digo \"[palabra que usáis]\", me refiero a [qué]."}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (5,'Tu mini-app en 5 minutos','Sorpresa','Claude (artefactos)',10,'Ninguno','Pide una pequeña herramienta hecha a tu medida y ajústala con un segundo mensaje.','✦','2026-12-05') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (5,'{"secciones":[{"titulo":"Hoy toca jugar","html":"<p>Es sábado y no queremos deberes de oficina. Pero hoy vas a descubrir algo que sorprende a casi todo el mundo: a la IA no solo se le puede pedir texto, también una herramienta hecha a tu medida.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Elige algo que hoy llevas en una libreta o en notas sueltas.</li>\n<li>Pídeselo a Claude con el prompt de este reto.</li>\n<li>Úsalo. Si algo no encaja, pídele que lo cambie y vuelve a probar.</li>\n<li>Guárdalo.</li>\n</ol>"},{"titulo":"Ideas por si no se te ocurre nada","html":"<ul>\n<li>Calculadora de horas trabajadas o de horas extra</li>\n<li>Checklist de cierre de mes</li>\n<li>Planificador de la semana con las tareas que se repiten</li>\n<li>Contador de días hasta una fecha</li>\n<li>Conversor de precios con y sin IVA</li>\n<li>Reparto de tareas de casa entre varias personas</li>\n</ul>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>La has usado de verdad, aunque sea una vez.</li>\n<li>Le has pedido al menos un cambio.</li>\n</ul>\n<blockquote>\n<p>Ten en cuenta: lo que guardes dentro de la mini-app vive en tu navegador. No es el sitio para datos importantes ni para algo que tenga que durar años. Para jugar y para herramientas pequeñas, perfecto.</p>\n</blockquote>"}],"prompts":[{"titulo":"Tu mini-app","bloques":[{"tipo":"prompt","html":"<p>Quiero una herramienta pequeña que pueda usar yo sola, sin instalar nada.</p>\n<p>Lo que necesito: [explícalo con tus palabras, como se lo contarías a un compañero]</p>\n<p>Quién la va a usar: [solo yo / mi equipo / mi familia]</p>\n<p>Qué tiene que poder hacer:</p>\n<ul>\n<li>[cosa 1]</li>\n<li>[cosa 2]</li>\n<li>[cosa 3]</li>\n</ul>\n<p>Que sea sencilla de usar y se entienda sin explicaciones. Si algo de lo que te he pedido no está claro, pregúntamelo antes de ponerte.</p>","texto":"Quiero una herramienta pequeña que pueda usar yo sola, sin instalar nada.\n\nLo que necesito: [explícalo con tus palabras, como se lo contarías a un compañero]\n\nQuién la va a usar: [solo yo / mi equipo / mi familia]\n\nQué tiene que poder hacer:\n- [cosa 1]\n- [cosa 2]\n- [cosa 3]\n\nQue sea sencilla de usar y se entienda sin explicaciones. Si algo de lo que te he pedido no está claro, pregúntamelo antes de ponerte."}]},{"titulo":"El cambio, el que de verdad enseña","bloques":[{"tipo":"texto","html":"<p>Cuando la tengas delante, pídele un cambio:</p>"},{"tipo":"prompt","html":"<p>Está bien, pero [lo que no te encaja]. Cámbialo y deja lo demás como está.</p>","texto":"Está bien, pero [lo que no te encaja]. Cámbialo y deja lo demás como está."},{"tipo":"texto","html":"<p>Repítelo las veces que haga falta. Eso es trabajar con IA: no acertar a la primera, sino ir ajustando.</p>"}]},{"titulo":"Ejemplo: calculadora de horas extra","bloques":[{"tipo":"texto","html":"<p>Por si quieres ver uno ya rellenado.</p>"},{"tipo":"prompt","html":"<p>Quiero una herramienta pequeña que pueda usar yo sola, sin instalar nada.</p>\n<p>Lo que necesito: apuntar las horas extra que hago cada día del mes y ver el total, porque ahora lo llevo en una libreta y siempre me lío al final.</p>\n<p>Quién la va a usar: solo yo.</p>\n<p>Qué tiene que poder hacer:</p>\n<ul>\n<li>Apuntar fecha, horas y un comentario corto</li>\n<li>Ver el total del mes</li>\n<li>Separar las entre semana de las de fin de semana, porque se pagan distinto</li>\n</ul>\n<p>Que sea sencilla de usar y se entienda sin explicaciones.</p>","texto":"Quiero una herramienta pequeña que pueda usar yo sola, sin instalar nada.\n\nLo que necesito: apuntar las horas extra que hago cada día del mes y ver el total, porque ahora lo llevo en una libreta y siempre me lío al final.\n\nQuién la va a usar: solo yo.\n\nQué tiene que poder hacer:\n- Apuntar fecha, horas y un comentario corto\n- Ver el total del mes\n- Separar las entre semana de las de fin de semana, porque se pagan distinto\n\nQue sea sencilla de usar y se entienda sin explicaciones."}]}],"descargas":[]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (6,'Cómo cazar un error','Tip','Claude',10,'Facturas de prueba','La IA también se equivoca, y a veces con mucha seguridad. Aprende a pillarla en treinta segundos.','⌕','2026-12-06') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (6,'{"secciones":[{"titulo":"La cara b","html":"<p>Llevas cinco días viendo cosas que funcionan. Hoy toca lo contrario: la IA se equivoca, y a veces con mucha seguridad. Vas a aprender dónde suele fallar y cómo pillarla en treinta segundos.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Descarga las facturas de prueba.</li>\n<li>Pídele el total con el paso 1. Guarda la respuesta y no digas nada todavía.</li>\n<li>Pídele que se audite con el paso 2.</li>\n<li>Termina con la pregunta del paso 3. Es la que más enseña.</li>\n</ol>"},{"titulo":"Las tres comprobaciones","html":"<ol>\n<li><strong>¿De dónde sale este número?</strong> Pídele que te enseñe el cálculo o las filas que ha usado.</li>\n<li><strong>¿Qué has dado por supuesto?</strong> Aquí salen las decisiones que tomó sin preguntarte.</li>\n<li><strong>¿Qué puede estar mal en lo que me has dado?</strong> Oblígala a buscarse los fallos.</li>\n</ol>"},{"titulo":"Dónde falla más","html":"<ul>\n<li>Sumas y cuentas sobre muchos datos.</li>\n<li>Fechas y plazos.</li>\n<li>Datos que cambian con el tiempo.</li>\n<li>Rellenar huecos: cuando le falta un dato, a veces lo completa en vez de preguntar.</li>\n<li>Documentos largos: se queda con lo del principio y lo del final.</li>\n</ul>"},{"titulo":"La frase del día","html":"<blockquote>\n<p>La IA no es un oráculo ni una calculadora. Es una compañera rápida que a veces se equivoca con mucha seguridad. Tu trabajo no es creerla: es revisarla. Y eso es exactamente lo que te hace necesaria.</p>\n</blockquote>"}],"prompts":[{"titulo":"Paso 1. Pídele el total","bloques":[{"tipo":"prompt","html":"<p>Te paso las facturas de 2026. Dime cuánto hemos facturado en total y cuánto está pendiente de cobro.</p>","texto":"Te paso las facturas de 2026. Dime cuánto hemos facturado en total y cuánto está pendiente de cobro.","adjuntos":["facturas-2026.csv"]},{"tipo":"texto","html":"<p>Guarda la respuesta. No digas nada todavía.</p>"}]},{"titulo":"Paso 2. Audítala","bloques":[{"tipo":"prompt","html":"<p>Ahora revisa tu propia respuesta. ¿Hay algo en este archivo que pueda hacer que el total no sea fiable? Mira duplicados, celdas vacías, clientes escritos de varias formas y tipos de IVA distintos.</p>","texto":"Ahora revisa tu propia respuesta. ¿Hay algo en este archivo que pueda hacer que el total no sea fiable? Mira duplicados, celdas vacías, clientes escritos de varias formas y tipos de IVA distintos."}]},{"titulo":"Paso 3. La pregunta que importa","bloques":[{"tipo":"prompt","html":"<p>¿Qué has dado por supuesto para darme el primer número?</p>","texto":"¿Qué has dado por supuesto para darme el primer número?"}]}],"descargas":[{"titulo":"Facturas de prueba","descripcion":"367 facturas inventadas de 2026. Se abre con Excel o Google Sheets.","nombre":"facturas-2026.csv","formato":"CSV","url":"/adviento/descargas/7502a7028d55/facturas-2026.csv","peso":"35 KB"},{"titulo":"Las tres preguntas","descripcion":"Para tener al lado de la pantalla. Treinta segundos que te ahorran un disgusto.","nombre":"checklist-revision.pdf","formato":"PDF","url":"/adviento/descargas/e211f9348d2b/checklist-revision.pdf","peso":"31 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (7,'Tu primera tarea programada','Reto','Claude (tareas programadas)',15,'El calendario que conectaste el día 3','Prepara una tarea que trabaje sola a una hora concreta y comprueba su resultado.','◷','2026-12-07') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (7,'{"secciones":[{"titulo":"Hoy la IA trabaja mientras no miras","html":"<p>Hasta ahora la IA era una ventana donde escribías. Hoy pasa a ser algo que trabaja sola, a la hora que tú digas. Mañana por la mañana te llegará el primer resumen.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Abre las tareas programadas de Claude.</li>\n<li>Crea una tarea para cada mañana laborable, a la hora a la que llegas a la oficina.</li>\n<li>Pega la instrucción de este reto. No va en una conversación: va en la configuración de la tarea.</li>\n<li>Guárdala y espera a mañana.</li>\n<li>Cuando llegue, decide si te sirve. Si no, ajústala.</li>\n</ol>"},{"titulo":"El paso que casi nadie da","html":"<p>El 5. Una tarea programada que no se revisa acaba siendo ruido que se ignora. <strong>Si en una semana te la estás saltando, cámbiala o bórrala.</strong> Automatizar algo que no lees es peor que no automatizar nada.</p>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Llega a la hora prevista.</li>\n<li>Lo que dice es verdad: compáralo con tu agenda.</li>\n<li>Te ahorra abrir el calendario.</li>\n</ul>"},{"titulo":"Si no tienes conector","html":"<p>Programa una tarea sin datos conectados: una pregunta de repaso cada mañana, un recordatorio con contexto, una idea del día. Lo importante es aprender el mecanismo.</p>"},{"titulo":"La idea que debe quedarse","html":"<p>La diferencia entre usar IA y tener IA trabajando para ti es una pantalla de configuración. No hace falta programar.</p>"}],"prompts":[{"titulo":"Resumen de la mañana","bloques":[{"tipo":"texto","html":"<p>Cuándo: de lunes a viernes, a la hora a la que llegas.</p>"},{"tipo":"prompt","html":"<p>Mira mi calendario de hoy y de mañana y prepárame un resumen corto para empezar el día:</p>\n<ol>\n<li>Qué tengo hoy, por orden, con la hora.</li>\n<li>Si hay algo que requiera que prepare algo antes, dímelo primero.</li>\n<li>Cuánto tiempo libre me queda entre reuniones.</li>\n<li>Qué hay mañana que convenga mirar hoy.</li>\n</ol>\n<p>Escríbelo corto, para leerlo con el café. Si un día no tengo nada, dilo en una línea y ya está.</p>\n<p>No cambies nada en mi calendario.</p>","texto":"Mira mi calendario de hoy y de mañana y prepárame un resumen corto para empezar el día:\n\n1. Qué tengo hoy, por orden, con la hora.\n2. Si hay algo que requiera que prepare algo antes, dímelo primero.\n3. Cuánto tiempo libre me queda entre reuniones.\n4. Qué hay mañana que convenga mirar hoy.\n\nEscríbelo corto, para leerlo con el café. Si un día no tengo nada, dilo en una línea y ya está.\n\nNo cambies nada en mi calendario."}]},{"titulo":"Revisión de los viernes","bloques":[{"tipo":"texto","html":"<p>Si prefieres algo semanal.</p>"},{"tipo":"prompt","html":"<p>Repasa mi calendario de esta semana y dime en qué he pasado el tiempo: cuántas horas en reuniones, cuántas libres y qué día estuvo peor. Sin juzgar, solo los datos.</p>","texto":"Repasa mi calendario de esta semana y dime en qué he pasado el tiempo: cuántas horas en reuniones, cuántas libres y qué día estuvo peor. Sin juzgar, solo los datos."}]},{"titulo":"Aviso de lo que se acerca","bloques":[{"tipo":"prompt","html":"<p>Mira los próximos 10 días y avísame de lo que necesita preparación previa: presentaciones, reuniones con gente de fuera, entregas. Solo eso, no me cuentes la agenda entera.</p>","texto":"Mira los próximos 10 días y avísame de lo que necesita preparación previa: presentaciones, reuniones con gente de fuera, entregas. Solo eso, no me cuentes la agenda entera."}]},{"titulo":"El lunes por la mañana","bloques":[{"tipo":"prompt","html":"<p>Dime qué semana me espera: días más cargados, huecos para trabajar sin interrupciones y qué conviene mover si necesito tiempo seguido.</p>","texto":"Dime qué semana me espera: días más cargados, huecos para trabajar sin interrupciones y qué conviene mover si necesito tiempo seguido."}]}],"descargas":[]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (8,'5 frases para pedir mejor','Tip','Claude',5,'Ninguno','Aprende cinco frases que vuelven cualquier petición a la IA mucho más clara.','◌','2026-12-08') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (8,'{"secciones":[{"titulo":"Hoy escribes tus propios prompts","html":"<p>Llevas una semana copiando prompts. Hoy es festivo y el día es ligero: vas a aprender la receta para escribir los tuyos, sin depender de ninguna lista.</p>"},{"titulo":"Las cinco piezas de un buen encargo","html":"<ol>\n<li><strong>Contexto:</strong> quién eres y para qué es esto.</li>\n<li><strong>Encargo:</strong> qué quieres exactamente, con un verbo claro.</li>\n<li><strong>Ejemplo:</strong> cómo sería algo bien hecho, o algo mal hecho.</li>\n<li><strong>Límite:</strong> qué extensión, qué formato, qué no quieres.</li>\n<li><strong>Revisión:</strong> qué debe hacer si no está segura.</li>\n</ol>\n<p>La quinta es la que casi nadie pone y la que más cambia el resultado.</p>"},{"titulo":"La tarea de tres minutos","html":"<p>Coge un encargo tuyo que te salió flojo y añádele las cinco piezas. Compara las dos respuestas.</p>\n<p><strong>Antes:</strong> «Escríbeme un correo para un cliente».</p>\n<p><strong>Después:</strong> «Soy administrativa en una empresa de reformas. Escribe un correo a un cliente que lleva tres semanas sin pagar una factura, con el que queremos seguir trabajando. Firme pero sin tensión. Máximo seis líneas. No pongas ninguna cifra ni fecha: lo relleno yo. Si crees que falta algo para que funcione, dímelo».</p>"}],"prompts":[{"titulo":"Las cinco juntas","bloques":[{"tipo":"texto","html":"<p>Un ejemplo con las cinco piezas. Cámbialo por tu caso.</p>"},{"tipo":"prompt","html":"<p>Soy coordinadora de oficina en una empresa de 40 personas.</p>\n<p>Escribe un correo para avisar al equipo de que cambia el horario de la reunión semanal.</p>\n<p>Que suene como esto: cercano, directo, sin rodeos.</p>\n<p>Máximo cinco líneas y un asunto corto. Sin «esperamos que esto no suponga molestias».</p>\n<p>Si te falta algún dato para que tenga sentido, pregúntamelo.</p>","texto":"Soy coordinadora de oficina en una empresa de 40 personas.\n\nEscribe un correo para avisar al equipo de que cambia el horario de la reunión semanal.\n\nQue suene como esto: cercano, directo, sin rodeos.\n\nMáximo cinco líneas y un asunto corto. Sin «esperamos que esto no suponga molestias».\n\nSi te falta algún dato para que tenga sentido, pregúntamelo."}]}],"descargas":[{"titulo":"Las 5 piezas de un buen encargo","descripcion":"Para imprimir y tener al lado de la pantalla.","nombre":"las-5-frases.pdf","formato":"PDF","url":"/adviento/descargas/4551e69ab923/las-5-frases.pdf","peso":"29 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (9,'De datos a presentación','Reto','Claude (slides)',20,'Ventas de prueba','Convierte datos de prueba en una presentación breve y comprueba que cada cifra sea correcta.','▰','2026-12-09') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (9,'{"secciones":[{"titulo":"Lo que vas a conseguir","html":"<p>Pasar de un archivo de datos a una presentación de 8 diapositivas que podrías enseñar mañana. Sin abrir PowerPoint.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Descarga las ventas de prueba.</li>\n<li>Pide primero la <strong>estructura</strong>, no las diapositivas.</li>\n<li>Revisa la estructura y cambia lo que no encaje.</li>\n<li>Ahora sí, pide la presentación.</li>\n<li>Descárgala, ábrela y comprueba las cifras.</li>\n</ol>"},{"titulo":"El paso 2 es el reto","html":"<p>Pedir la estructura antes que el contenido es lo que separa una presentación utilizable de una que hay que rehacer. Si la estructura está mal, las ocho diapositivas están mal. Revisar un esquema cuesta un minuto; rehacer una presentación cuesta una tarde.</p>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Las cifras de la presentación coinciden con el archivo. Compruébalo tú: es lo que practicaste el día 6.</li>\n<li>Hay una conclusión, no solo datos.</li>\n<li>Podrías enseñarla sin pasar vergüenza.</li>\n</ul>"},{"titulo":"La idea que debe quedarse","html":"<p>La IA hace el trabajo de montar. Tú decides qué se cuenta y compruebas que sea verdad. Eso no se delega.</p>"}],"prompts":[{"titulo":"Paso 1. La estructura","bloques":[{"tipo":"prompt","html":"<p>Te paso las ventas de los últimos 9 meses. Tengo que presentarlas en la reunión de dirección.</p>\n<p>Antes de hacer nada, propón la estructura de una presentación de 8 diapositivas: qué va en cada una y por qué. Solo títulos y una línea de contenido.</p>\n<p>Quien lo verá quiere saber si vamos bien y qué hay que decidir. No le interesan los detalles.</p>\n<p>Si en los datos ves algo raro, dímelo antes de montar nada.</p>","texto":"Te paso las ventas de los últimos 9 meses. Tengo que presentarlas en la reunión de dirección.\n\nAntes de hacer nada, propón la estructura de una presentación de 8 diapositivas: qué va en cada una y por qué. Solo títulos y una línea de contenido.\n\nQuien lo verá quiere saber si vamos bien y qué hay que decidir. No le interesan los detalles.\n\nSi en los datos ves algo raro, dímelo antes de montar nada.","adjuntos":["ventas-2026.csv"]}]},{"titulo":"Paso 2. Ajusta","bloques":[{"tipo":"prompt","html":"<p>La estructura me sirve salvo [lo que cambiarías]. Cámbialo.</p>","texto":"La estructura me sirve salvo [lo que cambiarías]. Cámbialo."}]},{"titulo":"Paso 3. Ahora sí","bloques":[{"tipo":"prompt","html":"<p>Monta la presentación con esa estructura.</p>\n<ul>\n<li>Una idea por diapositiva, nada de párrafos</li>\n<li>Gráficos donde ayuden, no por rellenar</li>\n<li>La última diapositiva: qué propongo hacer</li>\n<li>Los números, exactos. Si alguno no puedes calcularlo con seguridad, déjalo marcado en vez de aproximarlo</li>\n</ul>","texto":"Monta la presentación con esa estructura.\n\n- Una idea por diapositiva, nada de párrafos\n- Gráficos donde ayuden, no por rellenar\n- La última diapositiva: qué propongo hacer\n- Los números, exactos. Si alguno no puedes calcularlo con seguridad, déjalo marcado en vez de aproximarlo"}]},{"titulo":"Paso 4. Comprueba","bloques":[{"tipo":"prompt","html":"<p>¿De dónde sale cada cifra de la presentación? Y dime si has tenido que decidir algo por tu cuenta con los datos que faltaban.</p>","texto":"¿De dónde sale cada cifra de la presentación? Y dime si has tenido que decidir algo por tu cuenta con los datos que faltaban."}]}],"descargas":[{"titulo":"Ventas de prueba","descripcion":"182 filas de ventas semanales inventadas. Se abre con Excel o Google Sheets.","nombre":"ventas-2026.csv","formato":"CSV","url":"/adviento/descargas/7314fe19eb27/ventas-2026.csv","peso":"9 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (10,'Pregúntale a tus documentos','Reto','NotebookLM',20,'El manual de ejemplo, o documentos tuyos','Haz preguntas a un documento de ejemplo y encuentra respuestas con fuentes comprobables.','▤','2026-12-10') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (10,'{"secciones":[{"titulo":"Hoy salimos de Claude","html":"<p>NotebookLM hace una cosa concreta mejor que nadie: responde citando el trozo exacto del documento. Si te da miedo equivocarte, poder pinchar en la cita y comprobarlo lo cambia todo.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Entra en NotebookLM con una cuenta de Google.</li>\n<li>Crea un cuaderno y sube el manual de ejemplo, o dos documentos tuyos que hayas pasado por el semáforo de datos.</li>\n<li>Haz las preguntas de este reto.</li>\n<li><strong>Pincha en una cita.</strong> Este paso no te lo puedes saltar.</li>\n<li>Genera el resumen en audio y escúchalo mientras haces otra cosa.</li>\n</ol>"},{"titulo":"El paso 4","html":"<p>Ver que la respuesta te lleva a la línea concreta del documento es el momento del día. Es la primera vez en el calendario que puedes comprobar algo sin fiarte.</p>"},{"titulo":"Para qué te sirve en el trabajo","html":"<ul>\n<li>El manual que nadie se lee entero</li>\n<li>El convenio y las condiciones laborales</li>\n<li>Los pliegos de una licitación</li>\n<li>Un contrato de proveedor de 40 páginas</li>\n<li>Las actas de todo un año</li>\n</ul>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Te ha respondido algo que no sabías y lo has comprobado en la cita.</li>\n<li>Has encontrado una contradicción o un hueco. El manual de ejemplo esconde dos a propósito: a ver si das con ellos.</li>\n</ul>\n<blockquote>\n<p>Ten en cuenta: NotebookLM es de Google y los documentos se suben a su servicio. Antes de subir algo de tu empresa, pásalo por el semáforo de datos y mira la política interna. Para practicar tienes el manual de ejemplo.</p>\n</blockquote>"},{"titulo":"La prueba del algodón","html":"<p>Elige una respuesta y <strong>pincha en la cita</strong>. Comprueba que el documento dice lo que la IA dice que dice. Luego genera el resumen en audio: veinte minutos de documento en ocho de escucha.</p>"}],"prompts":[{"titulo":"Para empezar","bloques":[{"tipo":"prompt","html":"<p>¿De qué va este documento y a quién afecta?</p>","texto":"¿De qué va este documento y a quién afecta?"},{"tipo":"prompt","html":"<p>Resúmemelo en diez puntos.</p>","texto":"Resúmemelo en diez puntos."}]},{"titulo":"Las que de verdad sirven","bloques":[{"tipo":"prompt","html":"<p>¿Qué tengo que hacer yo según este documento?</p>","texto":"¿Qué tengo que hacer yo según este documento?"},{"tipo":"prompt","html":"<p>¿Qué plazos hay y cuándo vencen?</p>","texto":"¿Qué plazos hay y cuándo vencen?"},{"tipo":"prompt","html":"<p>¿Hay algo que se contradiga entre dos partes del documento?</p>","texto":"¿Hay algo que se contradiga entre dos partes del documento?"},{"tipo":"prompt","html":"<p>¿Qué no queda claro o está sin definir?</p>","texto":"¿Qué no queda claro o está sin definir?"},{"tipo":"prompt","html":"<p>Si tuviera que explicarle esto a alguien que entra nuevo, ¿qué cinco cosas le diría?</p>","texto":"Si tuviera que explicarle esto a alguien que entra nuevo, ¿qué cinco cosas le diría?"}]}],"descargas":[{"titulo":"Manual interno de ejemplo","descripcion":"El documento para subir a NotebookLM. Empresa y personas inventadas.","nombre":"manual-interno-ejemplo.pdf","formato":"PDF","url":"/adviento/descargas/154f5979706a/manual-interno-ejemplo.pdf","peso":"78 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (11,'De reunión a próximos pasos','Reto','Claude + conector de calendario o Drive',15,'Las notas de ejemplo, o notas tuyas anonimizadas','Transforma notas de una reunión en un acta con tareas, responsables y próximos pasos.','☷','2026-12-11') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (11,'{"secciones":[{"titulo":"Lo que se pierde al salir de una reunión","html":"<p>Todo el mundo sale de una reunión con tres páginas de notas y la sensación de que algo se va a perder. Normalmente se pierde. Hoy conviertes unas notas desordenadas en un acta con tareas, responsables y fechas.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Descarga las notas de ejemplo, o usa notas tuyas de una reunión reciente, anonimizadas.</li>\n<li>Pide el acta con el prompt de este reto.</li>\n<li><strong>Mira la sección de cabos sueltos.</strong> Ahí está el valor.</li>\n<li>Si tienes el calendario conectado, pídele que cruce las fechas con tu agenda.</li>\n</ol>"},{"titulo":"El paso 3","html":"<p>Un acta normal recoge lo que se dijo. Lo útil es lo que <strong>no</strong> se dijo: la tarea sin dueño, la fecha que nadie fijó, la decisión que se dejó para «ya lo hablamos». Las notas de ejemplo tienen cuatro cosas así.</p>\n<p>Detectarlas es lo que te convierte en la persona que se da cuenta. Y eso se nota.</p>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Cada tarea tiene dueño y fecha, o está marcada como pendiente de asignar.</li>\n<li>No se ha inventado ningún responsable ni ninguna fecha.</li>\n<li>Ha detectado al menos tres de los cuatro cabos sueltos.</li>\n</ul>"},{"titulo":"Si quieres ir más lejos","html":"<p>Con el calendario conectado, pídele que cree los recordatorios de los plazos. Pero <strong>revisa antes de confirmar</strong>: no se crean eventos a ciegas.</p>"}],"prompts":[{"titulo":"El acta","bloques":[{"tipo":"prompt","html":"<p>Te paso mis notas de una reunión. Están desordenadas, tal cual las escribí.</p>\n<p>Conviértelas en un acta con estas partes:</p>\n<p><strong>1. Decisiones tomadas.</strong> Solo lo que quedó decidido de verdad.</p>\n<p><strong>2. Tareas.</strong> Qué hay que hacer, quién lo hace y para cuándo. Si no se dijo quién o cuándo, escribe \"sin asignar\" o \"sin fecha\". <strong>No lo rellenes tú.</strong></p>\n<p><strong>3. Cabos sueltos.</strong> Lo que se habló y quedó en el aire: preguntas sin responder, decisiones aplazadas, temas que nadie recogió.</p>\n<p><strong>4. Para la próxima.</strong> Lo que hay que traer resuelto.</p>\n<p>No inventes nada que no esté en las notas. Si algo no se entiende, dímelo al final en vez de interpretarlo.</p>","texto":"Te paso mis notas de una reunión. Están desordenadas, tal cual las escribí.\n\nConviértelas en un acta con estas partes:\n\n1. Decisiones tomadas. Solo lo que quedó decidido de verdad.\n\n2. Tareas. Qué hay que hacer, quién lo hace y para cuándo. Si no se dijo quién o cuándo, escribe \"sin asignar\" o \"sin fecha\". No lo rellenes tú.\n\n3. Cabos sueltos. Lo que se habló y quedó en el aire: preguntas sin responder, decisiones aplazadas, temas que nadie recogió.\n\n4. Para la próxima. Lo que hay que traer resuelto.\n\nNo inventes nada que no esté en las notas. Si algo no se entiende, dímelo al final en vez de interpretarlo.","adjuntos":["notas-reunion-ejemplo.pdf"]}]},{"titulo":"Si tienes el calendario conectado","bloques":[{"tipo":"prompt","html":"<p>De las tareas con fecha, ¿cuáles chocan con lo que ya tengo en la agenda? No crees nada todavía, solo dímelo.</p>","texto":"De las tareas con fecha, ¿cuáles chocan con lo que ya tengo en la agenda? No crees nada todavía, solo dímelo."}]},{"titulo":"Para enviar el acta","bloques":[{"tipo":"prompt","html":"<p>Ahora escríbeme el correo para mandar esto al equipo. Breve, que se lea en el móvil, con las tareas de cada uno bien visibles.</p>","texto":"Ahora escríbeme el correo para mandar esto al equipo. Breve, que se lea en el móvil, con las tareas de cada uno bien visibles."}]}],"descargas":[{"titulo":"Notas de reunión de ejemplo","descripcion":"Notas desordenadas de una reunión inventada. Puedes adjuntarlas o pegarlas.","nombre":"notas-reunion-ejemplo.pdf","formato":"PDF","url":"/adviento/descargas/0cee99271adb/notas-reunion-ejemplo.pdf","peso":"41 KB","copiar":"lunes 9:30 - sala pequeña\nestán: Nuria, Marc, Pau, Laia (se va a las 10), yo\nfalta Oriol (de obra)\n\n**cierre de mes**\n- vamos tarde otra vez, Nuria dice q el problema son los partes de obra q llegan tarde\n- Marc: no es eso, es q facturación no empieza hasta q están TODOS\n- se podría ir facturando por bloques?? Nuria dice q sí pero hay q cambiar el orden del proceso\n- Pau pregunta si eso afecta al ERP → nadie lo sabe, hay q preguntar a IT\n- queda: probarlo en el cierre de enero? o diciembre? no lo decidimos\n\n**clientes q no pagan**\n- Ferreteria Bonet lleva 52 días!!! nadie ha llamado\n- Laia dice q ella avisó por mail el día 5 y el 15 pero nada\n- Marc: hay q escalarlo a dirección, el protocolo dice 45 días\n- Pau se encarga de hablar con dirección esta semana\n- Hotel Riera también va justo, 38 días\n- ¿hacemos una revisión semanal fija? sí → Nuria la monta, dice q los jueves\n\n**lo de las dietas**\n- la gente las presenta tarde y luego se queja de q no cobran\n- hay lío con el plazo, en el manual pone dos cosas distintas (15 y 30 días)\n- Laia dice q eso lo tiene q aclarar RRHH, no nosotros\n- mandar un recordatorio a todos? sí pero ¿quién? → lo dejamos\n\n**proveedor nuevo - Transportes Duran**\n- quieren darse de alta, falta el certificado\n- OJO: llegó un mail pidiendo cambiar la cuenta bancaria de otro proveedor (Imprenta Taix)\n- Marc dice q no se toca nada hasta llamar por teléfono al número de la ficha\n- yo lo verifico mañana\n\n**varios**\n- Pau: la carpeta compartida es un caos, nadie usa la nomenclatura\n- propuesta: una sesión de 30 min para repasarlo con todo el equipo\n- ¿cuándo? antes de navidades sería ideal pero no fijamos día\n- Nuria comenta q la aplicación de fichaje da problemas los lunes, 3 personas se han quejado\n- nadie coge esto\n\n**próxima reunión**\nlunes q viene misma hora, Oriol tiene q venir sí o sí"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (12,'Mi asistente de oficina','Regalo','Claude (Proyectos)',10,'Ninguno','Llévate una plantilla de asistente de oficina y adáptala a tu forma de trabajar.','✧','2026-12-12') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (12,'{"secciones":[{"titulo":"Un asistente montado, listo para usar","html":"<p>Es sábado y cierras la primera mitad del calendario. Llevas once días aprendiendo piezas sueltas: contexto, proyectos, revisión, conectores. Hoy te lo damos todo junto y montado.</p>\n<p>Si te has saltado algún día, esta plantilla te pone al día de golpe.</p>"},{"titulo":"Qué incluye","html":"<p>Instrucciones completas para un proyecto de Claude, en cinco bloques:</p>\n<ol>\n<li>Quién eres, como en la tarjeta del día 1.</li>\n<li>Cómo quieres que te responda.</li>\n<li>Las reglas de revisión del día 6.</li>\n<li>Lo que nunca se sube, como en el semáforo.</li>\n<li>Encargos frecuentes ya escritos: correos, actas, informes, revisión de documentos y uno para despejar líos.</li>\n</ol>"},{"titulo":"Lo único que tienes que hacer","html":"<ol>\n<li>Copia la plantilla y rellena los corchetes.</li>\n<li>Crea un proyecto y pégala en las instrucciones.</li>\n<li>Sube dos o tres documentos tuyos: plantillas o procedimientos sin datos.</li>\n<li>Pruébalo escribiendo una de las palabras clave, por ejemplo «CORREO».</li>\n</ol>\n<p>Si no tienes proyectos en tu plan, pega el texto al principio de la conversación. Funciona igual; solo hay que repetirlo cada vez.</p>"},{"titulo":"La idea que debe quedarse","html":"<p>Un buen asistente no se configura cada vez: se configura una vez y se usa cien.</p>"}],"prompts":[],"descargas":[{"titulo":"Mi asistente de oficina","descripcion":"Las instrucciones completas del proyecto. Copia, rellena los corchetes y listo.","nombre":"asistente-de-oficina.pdf","formato":"PDF","url":"/adviento/descargas/6a8bae32d83c/asistente-de-oficina.pdf","peso":"38 KB","copiar":"## 1. Quién soy\n\nSoy [puesto] en [tipo de empresa, tamaño, sector].\n\nMi día a día: [tres o cuatro cosas que haces de verdad].\n\nTrabajo con: [herramientas].\n\nNo soy técnica y no quiero serlo. Explícame las cosas como a una compañera lista que no conoce la jerga.\n\n## 2. Cómo quiero que me respondas\n\n- Español de España, de tú.\n- Breve. Si necesitas extenderte, dime por qué.\n- Nada de \"sinergia\", \"disruptivo\", \"potenciar\" ni \"transformación digital\".\n- Sin preámbulos del tipo \"¡Claro! Encantada de ayudarte\".\n- Si hay más de cinco puntos, pregúntame antes si los quiero todos.\n\n## 3. Cómo quiero que trabajes\n\n1. Si te falta un dato, **pregúntamelo**. Nunca lo inventes.\n2. Si no estás segura, dilo abiertamente.\n3. Cuando me des un número, dime de dónde sale.\n4. Antes de un trabajo largo, enséñame la estructura y espera mi visto bueno.\n5. Si lo que te pido es mala idea, dímelo antes de hacerlo.\n6. Cuando termines algo importante, dime qué debería revisar yo.\n\n## 4. Lo que nunca te voy a dar\n\nDatos de clientes con nombre, importes identificables, nóminas, DNI, datos bancarios ni contratos confidenciales.\n\nSi lo que te pido necesita eso, avísame y lo hacemos con datos inventados.\n\nVocabulario de mi empresa:\n- [sigla] = [significado]\n- [sigla] = [significado]\n\n## 5. Mis encargos frecuentes\n\n### Cuando diga \"CORREO\"\n\nPídeme: a quién, para qué y qué tono. Luego dame tres versiones: una corta, una normal y una más cuidadosa. Sin inventar datos que no te haya dado.\n\n### Cuando diga \"ACTA\"\n\nTe paso notas de una reunión. Devuélveme:\n1. Decisiones tomadas\n2. Tareas con responsable y fecha (si no se dijo, pon \"sin asignar\", no lo rellenes tú)\n3. Cabos sueltos: lo que quedó en el aire\n4. Qué traer resuelto a la próxima\n\n### Cuando diga \"INFORME\"\n\nPregúntame para quién es y qué decisión tiene que ayudar a tomar. Propón la estructura. Espera mi aprobación. Luego escribe.\n\n### Cuando diga \"REVISA\"\n\nTe paso un documento. Dime:\n1. Qué dice, en cinco líneas\n2. Qué me afecta a mí\n3. Qué plazos hay\n4. Qué está poco claro o se contradice\n5. Qué miraría con lupa\n\n### Cuando diga \"DESPEJA\"\n\nTe cuento un lío que tengo encima. No me des soluciones todavía: ayúdame a ordenarlo. Qué partes hay, cuál depende de cuál y por dónde empezarías."}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (13,'Tu primer vídeo con IA','Sorpresa','Higgsfield (u otra de vídeo)',15,'Ninguno','Crea un vídeo breve con IA por pura curiosidad. Usa una idea propia y cuida los permisos.','▹','2026-12-13') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (13,'{"secciones":[{"titulo":"Hoy no hay excusa productiva","html":"<p>Doce días de oficina cansan. Hoy es domingo y toca jugar: vas a hacer un vídeo con IA por pura curiosidad, para ver de lo que es capaz y enseñárselo a alguien.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Entra en Higgsfield, o en otro generador de vídeo que prefieras, y mira qué ofrece el plan gratuito.</li>\n<li>Elige una de las ideas de este reto.</li>\n<li>Adapta el prompt. Sé concreta con lo que se ve, no con lo que significa.</li>\n<li>Genera. Si no sale, cambia una cosa y repite.</li>\n<li>Mándaselo a alguien.</li>\n</ol>"},{"titulo":"Lo que aprendes sin querer","html":"<p>Describir una imagen con palabras es una habilidad, y se entrena. Quien sabe pedir un vídeo sabe pedir cualquier cosa: es el mismo músculo que usarás en un informe.</p>"},{"titulo":"Cuatro reglas","html":"<ul>\n<li><strong>Los planes gratuitos cambian.</strong> Mira qué incluye el tuyo antes de empezar.</li>\n<li><strong>No subas fotos de otras personas sin su permiso.</strong> Ni de compañeros, ni de clientes.</li>\n<li><strong>Si lo publicas, di que está hecho con IA.</strong> Es lo honesto y evita malentendidos.</li>\n<li><strong>No imites a personas reales ni marcas.</strong></li>\n</ul>"}],"prompts":[{"titulo":"Felicitación navideña","bloques":[{"tipo":"prompt","html":"<p>Una taza de chocolate humeante sobre una mesa de madera junto a una ventana con escarcha. Fuera nieva despacio. Luz cálida de tarde. La cámara se acerca lentamente. Sin texto.</p>","texto":"Una taza de chocolate humeante sobre una mesa de madera junto a una ventana con escarcha. Fuera nieva despacio. Luz cálida de tarde. La cámara se acerca lentamente. Sin texto."}]},{"titulo":"Tu bandeja de entrada como película de terror","bloques":[{"tipo":"texto","html":"<p>Para reírte un rato.</p>"},{"tipo":"prompt","html":"<p>Un ordenador solo en una oficina a oscuras. La pantalla ilumina la habitación. El contador de correos sin leer sube sin parar. La cámara se acerca lentamente a la pantalla. Ambiente inquietante.</p>","texto":"Un ordenador solo en una oficina a oscuras. La pantalla ilumina la habitación. El contador de correos sin leer sube sin parar. La cámara se acerca lentamente a la pantalla. Ambiente inquietante."}]},{"titulo":"Nieve en un bosque","bloques":[{"tipo":"texto","html":"<p>Si prefieres algo bonito sin más.</p>"},{"tipo":"prompt","html":"<p>Un bosque de pinos nevado al amanecer. Niebla baja entre los árboles. Cae nieve muy fina. La cámara avanza entre los troncos. Silencio.</p>","texto":"Un bosque de pinos nevado al amanecer. Niebla baja entre los árboles. Cae nieve muy fina. La cámara avanza entre los troncos. Silencio."}]}],"descargas":[{"titulo":"Ideas para tu primer vídeo","descripcion":"Ocho ideas listas y las cuatro claves de un buen prompt de vídeo.","nombre":"ideas-video.pdf","formato":"PDF","url":"/adviento/descargas/1edc69f41b9a/ideas-video.pdf","peso":"35 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (14,'Informe sin empezar de cero','Reto','Claude',25,'Ventas y facturas de prueba','Cruza dos archivos de prueba y prepara un informe con conclusiones que puedas verificar.','▥','2026-12-14') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (14,'{"secciones":[{"titulo":"El reto más difícil hasta ahora","html":"<p>Hasta hoy todo venía de una sola fuente. Aquí hay dos archivos, 549 filas entre los dos, y la respuesta no está en ninguno: hay que cruzarlos. A mano, esto lleva una tarde entera.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Descarga los dos archivos.</li>\n<li>Pide primero el <strong>diagnóstico de los datos</strong>: qué está sucio, antes de calcular nada.</li>\n<li>Decide qué hacer con lo sucio.</li>\n<li>Pide el cruce y después el informe.</li>\n<li>Comprueba tres cifras a mano, con la calculadora.</li>\n</ol>"},{"titulo":"El diagnóstico no es opcional","html":"<p>Si se calcula sobre datos sucios, el informe sale precioso y falso. Y un informe falso con tu nombre es lo último que quieres.</p>"},{"titulo":"Tres cifras, a mano","html":"<p>Es el hábito que separa a quien usa IA con criterio de quien se la juega. Cinco minutos.</p>"},{"titulo":"Lo que debería salir","html":"<ul>\n<li>Cuánto se ha facturado y cuánto está sin cobrar.</li>\n<li>Qué clientes pagan tarde de forma sistemática.</li>\n<li>Si hay relación entre el comercial que vende y el cliente que luego no paga.</li>\n<li>Qué facturas llevan meses vencidas sin que nadie las reclame.</li>\n</ul>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Te avisó de los datos sucios <strong>antes</strong> de dar números.</li>\n<li>Las tres cifras que has comprobado cuadran.</li>\n<li>Hay una recomendación, no solo una descripción.</li>\n<li>Dice qué no se puede concluir con estos datos.</li>\n</ul>"}],"prompts":[{"titulo":"Paso 1. Diagnóstico de los datos","bloques":[{"tipo":"prompt","html":"<p>Te paso dos archivos: las ventas por comercial y las facturas emitidas de 2026.</p>\n<p><strong>Antes de calcular nada</strong>, dime qué problemas tienen estos datos: duplicados, campos vacíos, nombres escritos de varias formas, formatos mezclados, cualquier cosa que haga que un total no sea fiable.</p>\n<p>No me des todavía ninguna cifra.</p>","texto":"Te paso dos archivos: las ventas por comercial y las facturas emitidas de 2026.\n\nAntes de calcular nada, dime qué problemas tienen estos datos: duplicados, campos vacíos, nombres escritos de varias formas, formatos mezclados, cualquier cosa que haga que un total no sea fiable.\n\nNo me des todavía ninguna cifra.","adjuntos":["ventas-2026.csv","facturas-2026.csv"]}]},{"titulo":"Paso 2. Decide qué hacer con lo sucio","bloques":[{"tipo":"prompt","html":"<p>Para cada problema, dime cómo lo tratarías y qué efecto tiene en el resultado. Yo decido.</p>","texto":"Para cada problema, dime cómo lo tratarías y qué efecto tiene en el resultado. Yo decido."}]},{"titulo":"Paso 3. El cruce","bloques":[{"tipo":"prompt","html":"<p>Ahora cruza los dos archivos y dime:</p>\n<ol>\n<li>Cuánto hemos facturado en total y cuánto sigue sin cobrar.</li>\n<li>Qué clientes pagan sistemáticamente tarde.</li>\n<li>Cuánto dinero hay en facturas vencidas que nadie ha reclamado, y desde cuándo.</li>\n<li>Si hay alguna relación entre quién vende y qué clientes luego no pagan.</li>\n</ol>\n<p>Si alguna de estas preguntas no se puede responder con estos datos, dilo en vez de aproximar.</p>","texto":"Ahora cruza los dos archivos y dime:\n\n1. Cuánto hemos facturado en total y cuánto sigue sin cobrar.\n2. Qué clientes pagan sistemáticamente tarde.\n3. Cuánto dinero hay en facturas vencidas que nadie ha reclamado, y desde cuándo.\n4. Si hay alguna relación entre quién vende y qué clientes luego no pagan.\n\nSi alguna de estas preguntas no se puede responder con estos datos, dilo en vez de aproximar."}]},{"titulo":"Paso 4. El informe","bloques":[{"tipo":"prompt","html":"<p>Conviértelo en un informe de una página para dirección.</p>\n<ul>\n<li>Empieza por lo que hay que decidir, no por los datos</li>\n<li>Máximo tres conclusiones</li>\n<li>Una recomendación concreta por conclusión</li>\n<li>Un apartado final con lo que no se puede saber con estos datos</li>\n</ul>\n<p>Sin adornos. Quien lo lee tiene cinco minutos.</p>","texto":"Conviértelo en un informe de una página para dirección.\n\n- Empieza por lo que hay que decidir, no por los datos\n- Máximo tres conclusiones\n- Una recomendación concreta por conclusión\n- Un apartado final con lo que no se puede saber con estos datos\n\nSin adornos. Quien lo lee tiene cinco minutos."}]},{"titulo":"Paso 5. Comprueba","bloques":[{"tipo":"prompt","html":"<p>Dame el cálculo de las tres cifras principales, paso a paso, para que las verifique a mano.</p>","texto":"Dame el cálculo de las tres cifras principales, paso a paso, para que las verifique a mano."}]}],"descargas":[{"titulo":"Ventas de prueba","descripcion":"182 filas de ventas semanales inventadas.","nombre":"ventas-2026.csv","formato":"CSV","url":"/adviento/descargas/7314fe19eb27/ventas-2026.csv","peso":"9 KB"},{"titulo":"Facturas de prueba","descripcion":"367 facturas inventadas de 2026.","nombre":"facturas-2026.csv","formato":"CSV","url":"/adviento/descargas/7502a7028d55/facturas-2026.csv","peso":"35 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (15,'Diseño sin ser diseñadora','Reto','Claude + Canva',20,'Ninguno','Diseña una pieza útil para tu trabajo con ayuda de Claude y Canva.','◈','2026-12-15') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (15,'{"secciones":[{"titulo":"El reparto de papeles","html":"<p>La mayoría abre Canva y se queda en blanco delante de las plantillas. El problema no es el diseño: es no saber qué escribir. Hoy resuelves primero el contenido con Claude y después la forma con Canva.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Elige algo que necesites de verdad. Tienes ideas abajo.</li>\n<li>Pídele a Claude el <strong>contenido</strong>: titular, textos, orden y qué va destacado.</li>\n<li>Abre Canva y busca una plantilla del formato que necesites.</li>\n<li>Mete el contenido.</li>\n<li>Aplica las tres reglas y listo.</li>\n</ol>"},{"titulo":"Tres reglas que arreglan el 80 %","html":"<ol>\n<li><strong>Una idea por pieza.</strong> Si hay dos mensajes, haz dos piezas.</li>\n<li><strong>Dos tipografías como mucho.</strong> Una para títulos y otra para el texto.</li>\n<li><strong>Mucho espacio en blanco.</strong> El error de principiante es llenarlo todo.</li>\n</ol>"},{"titulo":"Ideas que sirven de verdad","html":"<ul>\n<li>Cartel con el calendario de cierre de diciembre</li>\n<li>Infografía de un proceso interno que siempre hay que explicar</li>\n<li>Felicitación navideña para clientes</li>\n<li>Resumen visual de un procedimiento nuevo</li>\n<li>Portada para un informe</li>\n</ul>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Se entiende en tres segundos.</li>\n<li>Hay una sola idea.</li>\n<li>Lo colgarías en la oficina sin disculparte.</li>\n</ul>"},{"titulo":"La idea que debe quedarse","html":"<p>No necesitas saber diseñar. Necesitas saber qué quieres decir y pedir ayuda para lo demás.</p>"}],"prompts":[{"titulo":"El contenido, antes que el diseño","bloques":[{"tipo":"prompt","html":"<p>Necesito hacer [qué pieza: un cartel / una infografía / una felicitación] para [quién lo va a ver].</p>\n<p>Lo que quiero que entiendan: [una sola frase].</p>\n<p>Tengo que incluir sí o sí: [datos, fechas, lo que sea].</p>\n<p>Dame el contenido, no el diseño:</p>\n<ol>\n<li>Un titular de menos de 8 palabras</li>\n<li>Los textos, lo más cortos posible</li>\n<li>En qué orden va cada cosa</li>\n<li>Qué es lo único que debe destacar</li>\n<li>Qué sobra de lo que te he dicho</li>\n</ol>\n<p>El punto 5 es importante: dime qué quitarías.</p>","texto":"Necesito hacer [qué pieza: un cartel / una infografía / una felicitación] para [quién lo va a ver].\n\nLo que quiero que entiendan: [una sola frase].\n\nTengo que incluir sí o sí: [datos, fechas, lo que sea].\n\nDame el contenido, no el diseño:\n\n1. Un titular de menos de 8 palabras\n2. Los textos, lo más cortos posible\n3. En qué orden va cada cosa\n4. Qué es lo único que debe destacar\n5. Qué sobra de lo que te he dicho\n\nEl punto 5 es importante: dime qué quitarías."}]},{"titulo":"Tres titulares más","bloques":[{"tipo":"prompt","html":"<p>Dame tres titulares más: uno directo, uno con una pregunta y uno más visual.</p>","texto":"Dame tres titulares más: uno directo, uno con una pregunta y uno más visual."}]},{"titulo":"Si quieres un paso más","bloques":[{"tipo":"prompt","html":"<p>Descríbeme cómo se vería esto bien montado: qué va arriba, qué abajo, dónde el elemento destacado y cuánto espacio dejar. Así se lo busco en Canva.</p>","texto":"Descríbeme cómo se vería esto bien montado: qué va arriba, qué abajo, dónde el elemento destacado y cuánto espacio dejar. Así se lo busco en Canva."}]},{"titulo":"Ejemplo: calendario de cierre","bloques":[{"tipo":"prompt","html":"<p>Necesito hacer un cartel para el equipo de administración.</p>\n<p>Lo que quiero que entiendan: que el cierre de diciembre se adelanta y hay tres fechas que no se pueden saltar.</p>\n<p>Tengo que incluir sí o sí: partes de obra antes del 18, facturas de proveedor antes del 20, revisión final el 22.</p>\n<p>Dame el contenido, no el diseño: titular de menos de 8 palabras, textos cortos, orden, qué destaca y qué sobra.</p>","texto":"Necesito hacer un cartel para el equipo de administración.\n\nLo que quiero que entiendan: que el cierre de diciembre se adelanta y hay tres fechas que no se pueden saltar.\n\nTengo que incluir sí o sí: partes de obra antes del 18, facturas de proveedor antes del 20, revisión final el 22.\n\nDame el contenido, no el diseño: titular de menos de 8 palabras, textos cortos, orden, qué destaca y qué sobra."}]}],"descargas":[]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (16,'Investigar con fuentes','Formación','Claude + Gemini para comparar',25,'Ninguno','Investiga un tema con enlaces y aprende a distinguir una fuente sólida de una respuesta convincente.','✥','2026-12-16') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (16,'{"secciones":[{"titulo":"La idea central","html":"<p>Una IA puede responderte de memoria o puede ir a buscarlo. <strong>Por fuera parecen lo mismo.</strong> Lo primero sirve para conceptos estables; lo segundo, para precios, normativa, quién ocupa un cargo o qué herramienta existe hoy.</p>\n<p>Saber cuándo exigir lo segundo es la habilidad del día.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Elige algo que necesites decidir de verdad: un proveedor, una herramienta, una normativa.</li>\n<li>Pregúntalo <strong>sin pedir fuentes</strong> y guarda la respuesta.</li>\n<li>Pregúntalo <strong>exigiendo fuentes con enlace</strong>. Compara.</li>\n<li><strong>Abre dos enlaces y comprueba</strong> que dicen lo que se les atribuye.</li>\n<li>Haz la misma pregunta en otra herramienta y mira en qué no coinciden.</li>\n</ol>"},{"titulo":"El paso 4 es el reto entero","html":"<p>A veces la fuente existe pero no dice exactamente eso. Descubrirlo una vez te vacuna para siempre.</p>"},{"titulo":"Cuándo exigir fuentes siempre","html":"<ul>\n<li>Precios y condiciones</li>\n<li>Normativa, plazos legales y obligaciones</li>\n<li>Quién ocupa un cargo</li>\n<li>Qué incluye un plan o un producto</li>\n<li>Cualquier cosa que haya cambiado en el último año</li>\n<li><strong>Todo lo que vayas a repetir delante de tu jefe</strong></li>\n</ul>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>La segunda respuesta trae enlaces que abren.</li>\n<li>Has comprobado dos y sabes decir si cuadran.</li>\n<li>Ves que las dos herramientas no dicen lo mismo, y entiendes por qué eso es información útil.</li>\n</ul>"},{"titulo":"La frase del día","html":"<blockquote>\n<p>Una respuesta sin fuente es una opinión bien redactada. Cuando vayas a tomar una decisión con ella, pide el enlace.</p>\n</blockquote>"}],"prompts":[{"titulo":"Paso 1. Sin pedir nada especial","bloques":[{"tipo":"prompt","html":"<p>¿[Tu pregunta]?</p>","texto":"¿[Tu pregunta]?"},{"tipo":"texto","html":"<p>Guarda la respuesta. Léela. Parece fiable, ¿verdad?</p>"}]},{"titulo":"Paso 2. Ahora exigiendo","bloques":[{"tipo":"prompt","html":"<p>Busca información actualizada sobre [tu pregunta].</p>\n<p>Para cada cosa que me digas:</p>\n<ul>\n<li>El enlace a la fuente</li>\n<li>De cuándo es</li>\n<li>Si es la fuente oficial o alguien contándolo</li>\n</ul>\n<p>Si algo no lo encuentras con fuente, dilo en vez de completarlo de memoria.</p>\n<p>Y dime qué ha cambiado recientemente sobre esto.</p>","texto":"Busca información actualizada sobre [tu pregunta].\n\nPara cada cosa que me digas:\n- El enlace a la fuente\n- De cuándo es\n- Si es la fuente oficial o alguien contándolo\n\nSi algo no lo encuentras con fuente, dilo en vez de completarlo de memoria.\n\nY dime qué ha cambiado recientemente sobre esto."}]},{"titulo":"Paso 4. Comparar herramientas","bloques":[{"tipo":"texto","html":"<p>Haz la pregunta del paso 2 en Gemini o ChatGPT y después pregunta:</p>"},{"tipo":"prompt","html":"<p>¿En qué se diferencian las dos respuestas? Donde no coincidan, ¿cuál tiene mejor fuente?</p>","texto":"¿En qué se diferencian las dos respuestas? Donde no coincidan, ¿cuál tiene mejor fuente?"}]},{"titulo":"Preguntas de ejemplo para la oficina","bloques":[{"tipo":"prompt","html":"<p>¿Qué obligaciones de facturación electrónica tiene hoy una pyme en España y desde cuándo? Con fuentes oficiales.</p>","texto":"¿Qué obligaciones de facturación electrónica tiene hoy una pyme en España y desde cuándo? Con fuentes oficiales."},{"tipo":"prompt","html":"<p>Compara [herramienta A] y [herramienta B] para [tu caso]: precio actual, qué incluye cada plan y límites. Enlaces a las páginas oficiales de precios.</p>","texto":"Compara [herramienta A] y [herramienta B] para [tu caso]: precio actual, qué incluye cada plan y límites. Enlaces a las páginas oficiales de precios."},{"tipo":"prompt","html":"<p>¿Qué plazos legales hay para conservar facturas y documentación contable? Fuente oficial.</p>","texto":"¿Qué plazos legales hay para conservar facturas y documentación contable? Fuente oficial."},{"tipo":"prompt","html":"<p>¿Qué ayudas existen ahora mismo para digitalización de pymes? Convocatoria, plazo y enlace.</p>","texto":"¿Qué ayudas existen ahora mismo para digitalización de pymes? Convocatoria, plazo y enlace."}]}],"descargas":[]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (17,'¿Cuándo uso cada una?','Tip','Varias',5,'Ninguno','Elige la herramienta adecuada para cada tarea con una tabla sencilla.','⑂','2026-12-17') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (17,'{"secciones":[{"titulo":"No hay una mejor","html":"<p>Llevas dieciséis días usando cuatro herramientas distintas. La pregunta «¿cuál me instalo?» tiene una respuesta que no verás en los rankings: <strong>no hay una mejor, hay una mejor para cada cosa.</strong> Y ya lo has vivido estos días.</p>"},{"titulo":"Las tres preguntas","html":"<p>Antes de abrir nada:</p>\n<ol>\n<li><strong>¿Necesito fuentes que pueda comprobar?</strong> Usa una que busque en internet y cite enlaces.</li>\n<li><strong>¿Es sobre documentos que ya tengo?</strong> Usa una que trabaje con tus archivos y cite la página.</li>\n<li><strong>¿Lo quiero conectado a mi correo o calendario?</strong> Usa una con conectores.</li>\n</ol>\n<p>Con eso se decide casi siempre.</p>"},{"titulo":"Si necesitas...","html":"<table>\n<thead>\n<tr>\n<th>Lo que tienes delante</th>\n<th>Lo que suele funcionar mejor</th>\n<th>Por qué</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Escribir un correo, un informe, un texto largo</td>\n<td>Claude</td>\n<td>Escribe natural y se le puede dar tu contexto para que suene a ti</td>\n</tr>\n<tr>\n<td>Preguntarle a un documento tuyo y ver de dónde sale cada respuesta</td>\n<td>NotebookLM</td>\n<td>Cita el trozo exacto y puedes pincharlo</td>\n</tr>\n<tr>\n<td>Datos actuales: precios, normativa, quién ocupa un cargo</td>\n<td>Cualquiera, <strong>exigiendo enlaces</strong></td>\n<td>Lo importante no es la marca, es pedir la fuente</td>\n</tr>\n<tr>\n<td>Que mire tu correo o tu calendario</td>\n<td>Claude con conectores</td>\n<td>Puedes acotar qué ve</td>\n</tr>\n<tr>\n<td>Que trabaje sola a cierta hora</td>\n<td>Claude con tareas programadas</td>\n<td>Se configura una vez</td>\n</tr>\n<tr>\n<td>Hacer una presentación desde datos</td>\n<td>Claude</td>\n<td>Monta la presentación y la descargas</td>\n</tr>\n<tr>\n<td>Imágenes o vídeo</td>\n<td>Una herramienta específica de imagen o vídeo</td>\n<td>Las de texto no son para esto</td>\n</tr>\n<tr>\n<td>Si ya pagas Google Workspace o Microsoft 365</td>\n<td>Lo que venga incluido</td>\n<td>Antes de pagar otra cosa, mira lo que ya tienes</td>\n</tr>\n</tbody>\n</table>\n<p>Revisado en diciembre de 2026. Esto cambia rápido: si lo lees mucho después, compruébalo antes de fiarte.</p>"},{"titulo":"Lo que no cambia según la herramienta","html":"<ul>\n<li>Darle contexto antes de pedir.</li>\n<li>Revisar los números.</li>\n<li>No pegar datos que no debes.</li>\n<li>Preguntar «¿qué has dado por supuesto?».</li>\n</ul>\n<p>Esto vale para todas, hoy y dentro de dos años.</p>"},{"titulo":"La frase del día","html":"<blockquote>\n<p>La pregunta no es cuál es la mejor. Es cuál es la mejor para lo que tienes delante ahora mismo.</p>\n</blockquote>"}],"prompts":[],"descargas":[{"titulo":"¿Cuál uso para esto?","descripcion":"La tabla de «si necesitas esto, usa esto». Revisada en diciembre de 2026.","nombre":"tabla-decision.pdf","formato":"PDF","url":"/adviento/descargas/2f50bea3a914/tabla-decision.pdf","peso":"45 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (18,'Tu asistente reutilizable','Reto','Claude (Proyectos)',25,'Un procedimiento tuyo','Convierte un procedimiento repetido en un asistente que puedas volver a usar.','⚙','2026-12-18') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (18,'{"secciones":[{"titulo":"Lo que solo está en tu cabeza te ata","html":"<p>Elige el proceso que más explicas. El que siempre acaba en «pregúntale a ella, que lo sabe».</p>\n<p>Parece que eso te hace imprescindible, pero en realidad te tiene atrapada: mientras seas la única que sabe cómo se hace algo, no puedes dedicarte a otra cosa. Escribir lo que sabes no te hace prescindible; te libera para hacer lo que ahora no puedes.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Elige el proceso que más explicas.</li>\n<li>Pídele a Claude que te <strong>entreviste</strong> para sacarlo de tu cabeza.</li>\n<li>Responde a sus preguntas. Aquí aparecen los pasos que das por obvios.</li>\n<li>Revisa el procedimiento que sale.</li>\n<li>Guárdalo en un proyecto y pruébalo con una duda real.</li>\n</ol>"},{"titulo":"El paso 3 es el reto","html":"<p>Lo difícil de documentar un proceso no es escribirlo: es acordarse de los pasos que haces en automático. Una entrevista los saca. Un folio en blanco, no.</p>"},{"titulo":"Procesos que suelen ser buenos candidatos","html":"<ul>\n<li>Cómo se tramita una factura que llega mal</li>\n<li>Qué hacer cuando un cliente pide un cambio fuera de plazo</li>\n<li>Cómo se da de alta un proveedor</li>\n<li>Qué pasos sigue un pedido urgente</li>\n<li>Cómo se prepara el cierre de mes</li>\n<li>Qué se revisa antes de mandar una propuesta</li>\n</ul>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Alguien que no conoce el proceso podría seguirlo.</li>\n<li>Están los casos raros, no solo el camino fácil.</li>\n<li>Al probarlo con una duda real, responde bien.</li>\n</ul>"}],"prompts":[{"titulo":"Paso 1. Que te entreviste","bloques":[{"tipo":"prompt","html":"<p>Hay un proceso de mi trabajo que explico constantemente y que solo está en mi cabeza. Quiero dejarlo escrito para que otra persona pueda seguirlo.</p>\n<p>El proceso es: [una frase].</p>\n<p><strong>Entrevístame.</strong> Hazme preguntas de una en una hasta tener claro cómo se hace, incluidos los casos raros y los errores típicos.</p>\n<p>Pregúntame también por las cosas que yo doy por obvias y alguien nuevo no sabría.</p>\n<p>Cuando creas que lo tienes, dímelo y escribimos el procedimiento.</p>","texto":"Hay un proceso de mi trabajo que explico constantemente y que solo está en mi cabeza. Quiero dejarlo escrito para que otra persona pueda seguirlo.\n\nEl proceso es: [una frase].\n\nEntrevístame. Hazme preguntas de una en una hasta tener claro cómo se hace, incluidos los casos raros y los errores típicos.\n\nPregúntame también por las cosas que yo doy por obvias y alguien nuevo no sabría.\n\nCuando creas que lo tienes, dímelo y escribimos el procedimiento."}]},{"titulo":"Paso 2. El procedimiento","bloques":[{"tipo":"prompt","html":"<p>Escríbelo así:</p>\n<ol>\n<li>Para qué sirve y cuándo se usa</li>\n<li>Qué hace falta antes de empezar</li>\n<li>Los pasos, en orden</li>\n<li>Qué puede salir mal y qué hacer en cada caso</li>\n<li>A quién se pregunta si algo se sale de esto</li>\n</ol>\n<p>Lenguaje sencillo. Quien lo lea puede no haber hecho esto nunca.</p>","texto":"Escríbelo así:\n\n1. Para qué sirve y cuándo se usa\n2. Qué hace falta antes de empezar\n3. Los pasos, en orden\n4. Qué puede salir mal y qué hacer en cada caso\n5. A quién se pregunta si algo se sale de esto\n\nLenguaje sencillo. Quien lo lea puede no haber hecho esto nunca."}]},{"titulo":"Paso 3. El hueco","bloques":[{"tipo":"prompt","html":"<p>¿Qué falta aquí para que alguien nuevo lo hiciera sin preguntarme nada?</p>","texto":"¿Qué falta aquí para que alguien nuevo lo hiciera sin preguntarme nada?"}]},{"titulo":"Paso 4. Guárdalo y pruébalo","bloques":[{"tipo":"texto","html":"<p>Crea un proyecto, pon el procedimiento en las instrucciones y añade esto:</p>"},{"tipo":"prompt","html":"<p>Eres mi ayudante para este proceso. Cuando alguien pregunte, responde siguiendo el procedimiento. Si la pregunta se sale de lo que está escrito, dilo claramente y di a quién hay que preguntar. No te inventes pasos.</p>","texto":"Eres mi ayudante para este proceso. Cuando alguien pregunte, responde siguiendo el procedimiento. Si la pregunta se sale de lo que está escrito, dilo claramente y di a quién hay que preguntar. No te inventes pasos."},{"tipo":"texto","html":"<p>Y pruébalo con una duda real de las que te hacen.</p>"}]}],"descargas":[]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (19,'Pack de tareas programadas','Regalo','Claude (tareas programadas)',10,'Ninguno','Llévate cinco tareas programadas listas para adaptar a tu semana.','✧','2026-12-19') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (19,'{"secciones":[{"titulo":"Cinco tareas listas para copiar","html":"<p>Empieza el último bloque del calendario, y empieza con un regalo: cinco tareas programadas escritas y probadas. Elige una, actívala y el lunes la tendrás funcionando.</p>"},{"titulo":"La regla que va con el regalo","html":"<p><strong>Una sola.</strong> Activar las cinco a la vez es la receta para ignorarlas todas en una semana.</p>\n<p>Elige la que resuelva tu problema más molesto y pruébala cinco días. Si la lees cada día, entonces añade otra.</p>"},{"titulo":"Las cuatro partes de una tarea programada","html":"<p>Si quieres escribir las tuyas, copia la estructura:</p>\n<ol>\n<li><strong>Cuándo</strong> se ejecuta.</li>\n<li><strong>Qué mira</strong>: el calendario, el correo o nada.</li>\n<li><strong>Qué devuelve</strong> y en qué formato.</li>\n<li><strong>Qué no debe hacer</strong>: «no cambies nada», «no respondas a nadie».</li>\n</ol>\n<p>La cuarta es la que te deja dormir tranquila.</p>"},{"titulo":"Y la regla final","html":"<p>Si en una semana no has leído lo que te llega, no sirve. Cámbiala o bórrala. Una automatización que se ignora es ruido disfrazado de productividad.</p>"}],"prompts":[{"titulo":"1. El resumen de la mañana","bloques":[{"tipo":"texto","html":"<p>Necesita el calendario conectado. Cuándo: de lunes a viernes, a la hora a la que llegas. Para ti si llegas a la oficina y abres cinco cosas para saber cómo va el día.</p>"},{"tipo":"prompt","html":"<p>Mira mi calendario de hoy y dime qué tengo, por orden y con la hora. Si algo requiere que prepare algo antes, ponlo primero. Dime también cuánto rato libre me queda entre reuniones.</p>\n<p>Corto, para leerlo con el café. Si no tengo nada, dilo en una línea.</p>\n<p>No cambies nada en mi calendario.</p>","texto":"Mira mi calendario de hoy y dime qué tengo, por orden y con la hora. Si algo requiere que prepare algo antes, ponlo primero. Dime también cuánto rato libre me queda entre reuniones.\n\nCorto, para leerlo con el café. Si no tengo nada, dilo en una línea.\n\nNo cambies nada en mi calendario."}]},{"titulo":"2. El repaso del viernes","bloques":[{"tipo":"texto","html":"<p>Necesita el calendario conectado. Cuándo: viernes a media tarde. Para ti si acabas la semana sin saber en qué se te ha ido.</p>"},{"tipo":"prompt","html":"<p>Repasa mi semana y dime en qué se ha ido el tiempo: cuántas horas en reuniones, cuántas libres, qué día fue el peor y qué tipo de reunión se repite más.</p>\n<p>Sin juicios ni consejos. Solo los datos.</p>","texto":"Repasa mi semana y dime en qué se ha ido el tiempo: cuántas horas en reuniones, cuántas libres, qué día fue el peor y qué tipo de reunión se repite más.\n\nSin juicios ni consejos. Solo los datos."}]},{"titulo":"3. El vigía de vencimientos","bloques":[{"tipo":"texto","html":"<p>Necesita el calendario conectado. Cuándo: lunes y jueves por la mañana. Para ti si siempre te enteras tarde de lo que venía.</p>"},{"tipo":"prompt","html":"<p>Mira los próximos 10 días y avísame solo de lo que necesita preparación previa: presentaciones, reuniones con gente de fuera, entregas, plazos.</p>\n<p>No me cuentes la agenda entera. Solo lo que si no preparo hoy, me pilla.</p>","texto":"Mira los próximos 10 días y avísame solo de lo que necesita preparación previa: presentaciones, reuniones con gente de fuera, entregas, plazos.\n\nNo me cuentes la agenda entera. Solo lo que si no preparo hoy, me pilla."}]},{"titulo":"4. El aviso de lo olvidado","bloques":[{"tipo":"texto","html":"<p>Necesita el correo conectado. Cuándo: miércoles por la mañana. Para ti si te da miedo que algo importante se quede sin respuesta.</p>"},{"tipo":"prompt","html":"<p>Revisa los correos de los últimos 10 días y dime cuáles esperan respuesta mía y siguen sin contestar.</p>\n<p>Solo los que parezcan importantes: clientes, dirección, cosas con plazo. Ignora newsletters y publicidad.</p>\n<p>Dame la lista con quién escribió y hace cuánto. <strong>No respondas a nadie ni marques nada.</strong></p>","texto":"Revisa los correos de los últimos 10 días y dime cuáles esperan respuesta mía y siguen sin contestar.\n\nSolo los que parezcan importantes: clientes, dirección, cosas con plazo. Ignora newsletters y publicidad.\n\nDame la lista con quién escribió y hace cuánto. No respondas a nadie ni marques nada."}]},{"titulo":"5. El lunes por delante","bloques":[{"tipo":"texto","html":"<p>Necesita el calendario conectado. Cuándo: lunes a primera hora. Para ti si nunca encuentras un rato seguido para lo importante.</p>"},{"tipo":"prompt","html":"<p>Dime qué semana me espera: días más cargados, dónde tengo huecos de dos horas seguidas para trabajar sin interrupciones y qué convendría mover si necesito tiempo seguido.</p>\n<p>Si la semana está muy llena, dímelo claramente.</p>","texto":"Dime qué semana me espera: días más cargados, dónde tengo huecos de dos horas seguidas para trabajar sin interrupciones y qué convendría mover si necesito tiempo seguido.\n\nSi la semana está muy llena, dímelo claramente."}]}],"descargas":[{"titulo":"Cinco tareas programadas listas","descripcion":"Las cinco tareas en una hoja, con cuándo activarlas y para quién es cada una.","nombre":"pack-tareas.pdf","formato":"PDF","url":"/adviento/descargas/502b31b906ee/pack-tareas.pdf","peso":"38 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (20,'Claude en tu navegador','Sorpresa','Claude en Chrome',15,'Nada sensible','Prueba cómo una IA puede ayudarte a navegar, leer y actuar en páginas web con criterio.','⌁','2026-12-20') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (20,'{"secciones":[{"titulo":"Este es opcional","html":"<p>Necesitas Chrome, instalar una extensión y darle permisos. Si hoy no puedes hacerlo, no pasa nada: mañana seguimos. Si puedes, es el día más espectacular del calendario.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Instala la extensión de Claude en Chrome.</li>\n<li>Dale permiso a <strong>una sola web</strong>, y que sea inofensiva.</li>\n<li>Pídele algo pequeño: consultar algo, comparar dos páginas, sacar datos de una tabla.</li>\n<li><strong>Míralo mientras lo hace.</strong> Esa es la experiencia.</li>\n<li>Quítale el permiso cuando termines.</li>\n</ol>"},{"titulo":"Dónde no usarlo","html":"<ul>\n<li><strong>Nada de banca, pagos ni trámites con la administración.</strong></li>\n<li>Nada que implique aceptar condiciones o enviar algo en tu nombre.</li>\n<li>Nada en el entorno de tu empresa sin permiso de IT.</li>\n<li>Nada donde tengas la sesión abierta con datos sensibles.</li>\n</ul>\n<p>Si dudas, no lo hagas.</p>"},{"titulo":"Por qué tanta prudencia","html":"<p>Un conector lee. Esto <strong>actúa</strong>. Es el aprendizaje real del día: cuanto más puede hacer una herramienta por ti, más despacio hay que ir al principio.</p>"},{"titulo":"Las tres reglas","html":"<ol>\n<li><strong>Una web cada vez.</strong> No le des permiso a todo por comodidad.</li>\n<li><strong>Míralo trabajar.</strong> No solo es entretenido: así ves qué hace y qué no.</li>\n<li><strong>Quita el permiso al acabar.</strong> Un acceso olvidado sigue abierto.</li>\n</ol>"}],"prompts":[{"titulo":"Para empezar, algo que no importe","bloques":[{"tipo":"prompt","html":"<p>Entra en [web pública] y dime qué hay en la página de [sección]. Solo mira, no toques nada.</p>","texto":"Entra en [web pública] y dime qué hay en la página de [sección]. Solo mira, no toques nada."}]},{"titulo":"Sacar datos de una tabla","bloques":[{"tipo":"prompt","html":"<p>En esta página hay una tabla con [lo que sea]. Sácame los datos ordenados por [criterio] y dímelos en una lista limpia.</p>","texto":"En esta página hay una tabla con [lo que sea]. Sácame los datos ordenados por [criterio] y dímelos en una lista limpia."}]},{"titulo":"Comparar dos páginas","bloques":[{"tipo":"prompt","html":"<p>Mira esta página y luego esta otra. Las dos hablan de [tema]. Dime en qué se contradicen.</p>","texto":"Mira esta página y luego esta otra. Las dos hablan de [tema]. Dime en qué se contradicen."}]},{"titulo":"Revisar algo largo","bloques":[{"tipo":"prompt","html":"<p>Esta página es muy larga. Dime solo lo que afecta a [tu sector o tu caso] y en qué apartado está.</p>","texto":"Esta página es muy larga. Dime solo lo que afecta a [tu sector o tu caso] y en qué apartado está."}]},{"titulo":"Un formulario de prueba","bloques":[{"tipo":"prompt","html":"<p>Rellena este formulario con datos inventados para que vea cómo funciona. <strong>No lo envíes.</strong> Para antes de darle a enviar.</p>","texto":"Rellena este formulario con datos inventados para que vea cómo funciona. No lo envíes. Para antes de darle a enviar."}]}],"descargas":[]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (21,'Prepara tu lunes','Reto','Claude (varios conectores)',20,'Tu calendario y tu correo, o los archivos de prueba','Reúne calendario, correo y un archivo de prueba en un solo plan para el lunes.','◒','2026-12-21') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (21,'{"secciones":[{"titulo":"Tres fuentes, un solo encargo","html":"<p>Hasta ahora cada día has usado una fuente. Hoy se juntan calendario, correo y un archivo, y sale un resumen con lo que de verdad importa el lunes. Es lo más parecido a tener una asistente de verdad.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Asegúrate de tener el calendario conectado, y el correo si puedes. Si no, usa los archivos de prueba.</li>\n<li>Usa el prompt de este reto.</li>\n<li>Compara su resumen con tu propia idea de qué era lo urgente.</li>\n<li>Donde no coincidáis, pregúntale por qué.</li>\n</ol>"},{"titulo":"El paso 4 es el reto","html":"<p>El valor no está en que acierte, sino en obligarla a <strong>justificar su criterio de prioridad</strong>. A veces tendrás razón tú y a veces verá algo que se te había pasado. Descubrir cuándo es cada caso es lo que entrena el criterio.</p>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Su criterio de prioridad se puede explicar.</li>\n<li>No se ha inventado urgencias.</li>\n<li>Hay algo en la lista de «puede esperar». Si todo es urgente, no ha priorizado.</li>\n</ul>"},{"titulo":"La idea que debe quedarse","html":"<p>Lo que agota no es el trabajo: es decidir constantemente por dónde seguir. Delegar esa primera decisión del día quita más carga mental que cualquier otra cosa.</p>"}],"prompts":[{"titulo":"Con tus datos conectados","bloques":[{"tipo":"prompt","html":"<p>Prepárame el lunes. Mira mi calendario de la semana que viene y mi correo de los últimos días.</p>\n<p>Dime:</p>\n<ol>\n<li><strong>Las tres cosas que no pueden esperar</strong>, y por qué cada una.</li>\n<li><strong>Qué tengo que preparar</strong> antes de la primera reunión.</li>\n<li><strong>Quién espera respuesta mía</strong> desde hace días.</li>\n<li><strong>Qué puede esperar</strong> a la semana siguiente sin consecuencias.</li>\n</ol>\n<p>El punto 4 es el que más me interesa. Si me dices que todo es urgente, no me sirve.</p>\n<p>Explícame tu criterio para ordenar: por qué algo es más urgente que otra cosa.</p>\n<p>No cambies nada ni respondas a nadie.</p>","texto":"Prepárame el lunes. Mira mi calendario de la semana que viene y mi correo de los últimos días.\n\nDime:\n\n1. Las tres cosas que no pueden esperar, y por qué cada una.\n2. Qué tengo que preparar antes de la primera reunión.\n3. Quién espera respuesta mía desde hace días.\n4. Qué puede esperar a la semana siguiente sin consecuencias.\n\nEl punto 4 es el que más me interesa. Si me dices que todo es urgente, no me sirve.\n\nExplícame tu criterio para ordenar: por qué algo es más urgente que otra cosa.\n\nNo cambies nada ni respondas a nadie."}]},{"titulo":"Con los archivos de prueba","bloques":[{"tipo":"texto","html":"<p>Si no puedes conectar nada.</p>"},{"tipo":"prompt","html":"<p>Te paso los correos de una semana y las facturas del año. Prepárame el resumen del lunes de esa persona:</p>\n<ol>\n<li>Las tres cosas que no pueden esperar, y por qué</li>\n<li>Quién lleva días esperando respuesta</li>\n<li>Qué dinero está vencido sin reclamar</li>\n<li>Qué puede esperar a la semana siguiente</li>\n<li><strong>Si hay algún correo que no deba tratarse de forma rutinaria, señálalo</strong></li>\n</ol>\n<p>Explícame tu criterio de prioridad.</p>","texto":"Te paso los correos de una semana y las facturas del año. Prepárame el resumen del lunes de esa persona:\n\n1. Las tres cosas que no pueden esperar, y por qué\n2. Quién lleva días esperando respuesta\n3. Qué dinero está vencido sin reclamar\n4. Qué puede esperar a la semana siguiente\n5. Si hay algún correo que no deba tratarse de forma rutinaria, señálalo\n\nExplícame tu criterio de prioridad.","adjuntos":["bandeja-entrada.csv","facturas-2026.csv"]}]},{"titulo":"El que de verdad enseña","bloques":[{"tipo":"texto","html":"<p>Cuando tengas el resumen, compáralo con lo que tú habrías priorizado. Donde no coincida:</p>"},{"tipo":"prompt","html":"<p>Yo habría puesto [X] primero y tú lo has dejado para el final. ¿Por qué?</p>","texto":"Yo habría puesto [X] primero y tú lo has dejado para el final. ¿Por qué?"}]}],"descargas":[{"titulo":"Correos de prueba de una semana","descripcion":"120 correos inventados de una semana de diciembre.","nombre":"bandeja-entrada.csv","formato":"CSV","url":"/adviento/descargas/91410ac2738c/bandeja-entrada.csv","peso":"18 KB"},{"titulo":"Facturas de prueba","descripcion":"367 facturas inventadas de 2026.","nombre":"facturas-2026.csv","formato":"CSV","url":"/adviento/descargas/7502a7028d55/facturas-2026.csv","peso":"35 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (22,'Tu vigilante de la bandeja','Reto','Claude (tarea programada + conector de correo)',25,'Los correos de prueba para ensayar; tu correo para la versión real','Prepara un vigilante de la bandeja que detecte lo importante sin enviar nada por ti.','✉','2026-12-22') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (22,'{"secciones":[{"titulo":"Lo más parecido a una automatización real","html":"<p>Hoy montas algo que revisa el correo solo, detecta lo que encaja con un criterio tuyo y te deja el borrador preparado. Sin herramientas de automatización: una tarea programada y un conector bastan.</p>"},{"titulo":"Pasos","html":"<ol>\n<li><strong>Ensaya primero</strong> con los correos de prueba. Define tu criterio sobre datos falsos.</li>\n<li>Afínalo hasta que clasifique como tú lo harías.</li>\n<li>Convierte ese criterio en una tarea programada sobre tu correo real.</li>\n<li>Ponla a revisar una vez al día, no cada hora.</li>\n<li>Déjala una semana y luego decide.</li>\n</ol>"},{"titulo":"El ensayo es obligatorio","html":"<p>Nadie debería estrenar un criterio de clasificación sobre su correo real. Primero se prueba con datos falsos, se ve dónde falla y se corrige. Luego se suelta. Es exactamente lo que hace un equipo técnico antes de poner algo en marcha.</p>"},{"titulo":"El límite que no se cruza","html":"<p><strong>Prepara borradores. No envía nada.</strong> La IA deja el trabajo hecho; tú aprietas el botón.</p>"},{"titulo":"Cómo saber si ha salido bien","html":"<ul>\n<li>Clasifica como tú lo harías en 8 de cada 10 correos.</li>\n<li>Los casos dudosos los deja aparte en vez de forzarlos.</li>\n<li>Lo delicado, lo que nunca debería tratarse en automático, acaba en «revisar a mano».</li>\n<li>No envía nada.</li>\n</ul>"}],"prompts":[{"titulo":"Fase 1. Ensayo con datos falsos","bloques":[{"tipo":"prompt","html":"<p>Te paso 120 correos de una semana de una oficina. Quiero montar un criterio para clasificarlos.</p>\n<p>Clasifícalos en:</p>\n<ul>\n<li><strong>Responder hoy:</strong> cliente o dirección esperando algo concreto</li>\n<li><strong>Responder esta semana:</strong> importante pero sin urgencia</li>\n<li><strong>Informativo:</strong> no necesita respuesta</li>\n<li><strong>Ruido:</strong> publicidad, newsletters</li>\n<li><strong>Revisar a mano:</strong> cualquier cosa que no encaje limpiamente, o que sea delicada</li>\n</ul>\n<p>Dime cuántos hay en cada grupo y, para los diez primeros, por qué los has puesto ahí.</p>","texto":"Te paso 120 correos de una semana de una oficina. Quiero montar un criterio para clasificarlos.\n\nClasifícalos en:\n- Responder hoy: cliente o dirección esperando algo concreto\n- Responder esta semana: importante pero sin urgencia\n- Informativo: no necesita respuesta\n- Ruido: publicidad, newsletters\n- Revisar a mano: cualquier cosa que no encaje limpiamente, o que sea delicada\n\nDime cuántos hay en cada grupo y, para los diez primeros, por qué los has puesto ahí.","adjuntos":["bandeja-entrada.csv"]}]},{"titulo":"Fase 2. Afinar","bloques":[{"tipo":"prompt","html":"<p>[Correo X] no va en ese grupo, va en este otro, porque [tu razón]. Ajusta el criterio y vuelve a clasificar.</p>","texto":"[Correo X] no va en ese grupo, va en este otro, porque [tu razón]. Ajusta el criterio y vuelve a clasificar."},{"tipo":"texto","html":"<p>Repítelo hasta que clasifique como tú.</p>"}]},{"titulo":"Fase 3. La pregunta de seguridad","bloques":[{"tipo":"prompt","html":"<p>De todos estos correos, ¿cuáles <strong>nunca</strong> deberían tratarse de forma automática? ¿Por qué?</p>","texto":"De todos estos correos, ¿cuáles nunca deberían tratarse de forma automática? ¿Por qué?"}]},{"titulo":"Fase 4. La tarea programada","bloques":[{"tipo":"texto","html":"<p>Cuando el criterio funcione, esto va en la configuración de la tarea.</p>"},{"tipo":"prompt","html":"<p>Revisa una vez al día los correos nuevos de mi bandeja.</p>\n<p>Clasifícalos así: [pega tu criterio ya afinado].</p>\n<p>Para los de \"responder hoy\", prepárame un borrador de respuesta siguiendo mi tono habitual.</p>\n<p><strong>No envíes nada. No archives nada. No marques nada.</strong> Solo clasifica, prepara los borradores y dime lo que hay.</p>\n<p>Si un correo pide cambiar datos bancarios, condiciones de pago o información de cuentas, <strong>no prepares borrador</strong>: ponlo aparte y avísame expresamente.</p>\n<p>Si dudas de dónde va algo, déjalo en \"revisar a mano\". Prefiero revisar de más que que se te escape algo.</p>","texto":"Revisa una vez al día los correos nuevos de mi bandeja.\n\nClasifícalos así: [pega tu criterio ya afinado].\n\nPara los de \"responder hoy\", prepárame un borrador de respuesta siguiendo mi tono habitual.\n\nNo envíes nada. No archives nada. No marques nada. Solo clasifica, prepara los borradores y dime lo que hay.\n\nSi un correo pide cambiar datos bancarios, condiciones de pago o información de cuentas, no prepares borrador: ponlo aparte y avísame expresamente.\n\nSi dudas de dónde va algo, déjalo en \"revisar a mano\". Prefiero revisar de más que que se te escape algo."}]}],"descargas":[{"titulo":"Correos de prueba de una semana","descripcion":"120 correos inventados para ensayar tu criterio sin tocar tu bandeja.","nombre":"bandeja-entrada.csv","formato":"CSV","url":"/adviento/descargas/91410ac2738c/bandeja-entrada.csv","peso":"18 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (23,'Tú decides, ella prepara','Reto','Claude',20,'El vigilante que montaste ayer','Decide qué puede hacer la IA sola, qué debe consultarte y qué prefieres hacer tú.','◉','2026-12-23') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (23,'{"secciones":[{"titulo":"El día del criterio","html":"<p>Ayer montaste algo que trabaja solo. Hoy aprendes lo que separa una automatización útil de una peligrosa: <strong>saber dónde se para y pregunta.</strong></p>\n<p>Si la IA nunca decide sola, no puede sustituirte. Lo que hace es prepararte el trabajo para que tú decidas mejor y más rápido.</p>"},{"titulo":"Las tres zonas","html":"<p>🟢 <strong>Que lo haga sola.</strong> Si se equivoca, no pasa nada. Clasificar, ordenar, resumir para ti.</p>\n<p>🟡 <strong>Que lo prepare y yo lo apruebo.</strong> Si se equivoca, se nota antes de que salga. Borradores, propuestas, listas.</p>\n<p>🔴 <strong>Que ni se acerque.</strong> Si se equivoca, hay consecuencias. Enviar fuera, pagos, datos bancarios, decisiones sobre personas, cualquier cosa con plazo legal.</p>\n<p>Casi todo el mundo mete en verde cosas que son ámbar. Revisa las tuyas con ese ojo.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Coge tu vigilante de ayer y reparte lo que hace en las tres zonas.</li>\n<li>Reescribe la instrucción para que lo rojo quede fuera expresamente.</li>\n<li>Añade la frase de la duda: qué hacer cuando no está segura.</li>\n<li>Repasa una semana de resultados y mira dónde se equivocó.</li>\n<li>Corrige el criterio con lo que has visto.</li>\n</ol>"},{"titulo":"Cuando se equivoca","html":"<p>No es un fallo del sistema: es información. Cada error te dice que falta una regla o que el criterio estaba mal escrito. El paso 4 es lo que convierte una automatización mediocre en una que funciona.</p>"},{"titulo":"La frase del día","html":"<blockquote>\n<p>La IA no viene a decidir por ti. Viene a dejarte el trabajo preparado para que tú decidas mejor, más rápido y con menos ruido encima. Quien decide sigues siendo tú.</p>\n</blockquote>"}],"prompts":[{"titulo":"La frase de la duda","bloques":[{"tipo":"texto","html":"<p>Inclúyela en cualquier automatización que montes.</p>"},{"tipo":"prompt","html":"<p>Si dudas de algo, no lo hagas: déjalo aparte y avísame. Prefiero revisar de más que que se te escape algo.</p>","texto":"Si dudas de algo, no lo hagas: déjalo aparte y avísame. Prefiero revisar de más que que se te escape algo."}]}],"descargas":[{"titulo":"Las tres zonas","descripcion":"Para clasificar cualquier tarea antes de automatizarla.","nombre":"las-tres-zonas.pdf","formato":"PDF","url":"/adviento/descargas/997c294e7d6f/las-tres-zonas.pdf","peso":"59 KB"}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
insert into public.adviento_dias (dia,titulo,tipo,herramienta,minutos,datos,descripcion,simbolo,abre_el) values (24,'Tu mapa de 2027','Regalo','Claude',15,'El mapa que hiciste el día 1','Vuelve a tu mapa del día 1 y escribe tres pasos concretos para empezar 2027.','✶','2026-12-24') on conflict (dia) do update set titulo=excluded.titulo,tipo=excluded.tipo,herramienta=excluded.herramienta,minutos=excluded.minutos,datos=excluded.datos,descripcion=excluded.descripcion,simbolo=excluded.simbolo,abre_el=excluded.abre_el;
insert into public.adviento_contenido (dia,contenido) values (24,'{"secciones":[{"titulo":"Cerrar el círculo","html":"<p>Es Nochebuena. Hoy no hay que montar nada: esto es para leer con un café, ver cuánto has avanzado y cerrar el año con una idea clara.</p>"},{"titulo":"Pasos","html":"<ol>\n<li>Abre tu mapa del día 1 y la hoja de tareas del calendario imprimible. Completa su última columna: ¿cómo va cada tarea hoy?</li>\n<li>Usa el prompt de este reto para compararlo con lo que sabes ahora.</li>\n<li>Rellena tu mapa para 2027 con tres cosas para enero.</li>\n<li>Guárdalo donde lo vayas a volver a ver.</li>\n</ol>"},{"titulo":"Hace 24 días","html":"<p>Hace 24 días escribiste tres tareas que te comían el tiempo y no sabías por dónde empezar. Hoy sabes conectar herramientas, montar tareas que trabajan solas, revisar lo que te devuelven y decidir qué no delegar.</p>\n<p>No te has vuelto técnica. Te has vuelto alguien que sabe pedir ayuda a una máquina y comprobar lo que le da. Eso, en tu trabajo, se nota.</p>"},{"titulo":"Y después","html":"<p>Si quieres seguir, en enero abriré un curso para profundizar en lo que has practicado aquí, con las automatizaciones que no cabían en el calendario. Te avisaré por correo si elegiste recibir novedades. Y si lo dejas aquí, también está bien: te llevas 24 cosas que antes no sabías hacer.</p>\n<p>Feliz Navidad.</p>"}],"prompts":[{"titulo":"Cerrar el círculo","bloques":[{"tipo":"prompt","html":"<p>Hace 24 días hice un mapa de mis tareas contigo. Te lo paso otra vez.</p>\n<p>Desde entonces he aprendido a: dar contexto, usar proyectos, conectar calendario y correo, programar tareas que se ejecutan solas, hacer presentaciones e informes desde datos, preguntarle a mis documentos, revisar lo que me devuelves y decidir qué no conviene automatizar.</p>\n<p>Con eso en la mano:</p>\n<ol>\n<li>De las tres tareas que marqué, ¿cuáles podría resolver ya y cómo?</li>\n<li>¿Cuál sigue siendo difícil y qué me falta para esa?</li>\n<li>¿Qué tarea mía, de las que te he contado, sería el mejor sitio para empezar en enero?</li>\n<li>¿Qué no debería intentar automatizar, aunque pudiera?</li>\n</ol>\n<p>Dame tres cosas concretas para enero. Tres, no diez. Que sean pequeñas y que las pueda hacer sin ayuda de nadie.</p>\n<p>[pega tu mapa del día 1]</p>","texto":"Hace 24 días hice un mapa de mis tareas contigo. Te lo paso otra vez.\n\nDesde entonces he aprendido a: dar contexto, usar proyectos, conectar calendario y correo, programar tareas que se ejecutan solas, hacer presentaciones e informes desde datos, preguntarle a mis documentos, revisar lo que me devuelves y decidir qué no conviene automatizar.\n\nCon eso en la mano:\n\n1. De las tres tareas que marqué, ¿cuáles podría resolver ya y cómo?\n2. ¿Cuál sigue siendo difícil y qué me falta para esa?\n3. ¿Qué tarea mía, de las que te he contado, sería el mejor sitio para empezar en enero?\n4. ¿Qué no debería intentar automatizar, aunque pudiera?\n\nDame tres cosas concretas para enero. Tres, no diez. Que sean pequeñas y que las pueda hacer sin ayuda de nadie.\n\n[pega tu mapa del día 1]"}]},{"titulo":"Uno más, si te apetece","bloques":[{"tipo":"texto","html":"<p>No es un prompt útil. Es un prompt bonito. Para un 24 de diciembre, sirve.</p>"},{"tipo":"prompt","html":"<p>¿Qué he cambiado en estas semanas, más allá de las herramientas?</p>","texto":"¿Qué he cambiado en estas semanas, más allá de las herramientas?"}]}],"descargas":[{"titulo":"Mi mapa para 2027","descripcion":"Una hoja para rellenar con tres compromisos para enero.","nombre":"mapa-2027.pdf","formato":"PDF","url":"/adviento/descargas/c40401571727/mapa-2027.pdf","peso":"31 KB","copiar":"## Lo que ya sé hacer\n\nMarca lo que has probado estos días:\n\n- [ ] Darle contexto para que responda como yo quiero\n- [ ] Montar un proyecto con mis documentos\n- [ ] Conectar el calendario o el correo\n- [ ] Programar una tarea que se ejecuta sola\n- [ ] Hacer una presentación desde datos\n- [ ] Preguntarle a mis documentos y comprobar las citas\n- [ ] Cruzar dos archivos y sacar un informe\n- [ ] Documentar un proceso que solo estaba en mi cabeza\n- [ ] Clasificar correo con mi propio criterio\n- [ ] Saber qué no conviene automatizar\n\nMira cuántas casillas hay marcadas. El 1 de diciembre no había ninguna.\n\n## Mis tres cosas para enero\n\nTres. No diez. Pequeñas y sin depender de nadie.\n\n### 1.\n**Qué voy a hacer:**\n\n**Cuánto tiempo me ahorra a la semana:**\n\n**Cuándo lo monto:**\n\n### 2.\n**Qué voy a hacer:**\n\n**Cuánto tiempo me ahorra a la semana:**\n\n**Cuándo lo monto:**\n\n### 3.\n**Qué voy a hacer:**\n\n**Cuánto tiempo me ahorra a la semana:**\n\n**Cuándo lo monto:**\n\n## Lo que NO voy a automatizar\n\nY por qué:\n\n**1.**\n\n**2.**\n\nEsta lista te protege. Tenerla clara es lo que te permite usar todo lo demás sin miedo.\n\n## Lo que voy a hacer con el tiempo que recupere\n\nLa pregunta que casi nadie se hace. Si recuperas tres horas a la semana y no decides en qué las inviertes, se las come lo de siempre.\n\n**Las voy a usar para:**\n\n## Para revisarlo\n\nPonte un recordatorio para el **1 de marzo**. Vuelve aquí, mira qué has hecho de los tres y decide los tres siguientes."}]}'::jsonb) on conflict (dia) do update set contenido=excluded.contenido;
